param([int]$Port = 8090)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Data
$Base=Join-Path $PSScriptRoot 'PanelData';New-Item -ItemType Directory -Path $Base -Force|Out-Null
$ProfileFile=Join-Path $Base 'profiles.json';$AuditFile=Join-Path $Base 'audit.log'
$ClientRoot='D:\NOVO SERVER S6\Cliente - Season 6 21.1.0\Cliente'
if(!(Test-Path $ProfileFile)){@([ordered]@{Id='season6-local';Name='Season 6 21.1.0 • Local';Root='D:\NOVO SERVER S6\MuServer - Season 6 21.1.0\MuServer';Dsn='MuOnlineS6'})|ConvertTo-Json|Set-Content $ProfileFile -Encoding UTF8}
$Profiles=@(Get-Content $ProfileFile -Raw|ConvertFrom-Json);$Active=$Profiles[0].Id
function Profile{$p=@($Profiles|? Id -eq $Active)|select -First 1;if(!$p){$p=$Profiles[0];$script:Active=$p.Id};$p}
function Root{[string](Profile).Root};function Dsn{[string](Profile).Dsn}
function Audit([string]$a,[string]$d=''){Add-Content $AuditFile -Encoding UTF8 -Value ('{0:u}'+[char]9+'{1}'+[char]9+'{2}'+[char]9+'{3}'-f(Get-Date),(Profile).Id,$a,$d.Replace([char]13,' ').Replace([char]10,' '))}
function Conn{$c=New-Object System.Data.Odbc.OdbcConnection("DSN=$(Dsn);");$c.Open();$c}
function Params($q,[object[]]$v){foreach($x in @($v)){$p=$q.Parameters.Add('?', [System.Data.Odbc.OdbcType]::VarChar,4000);$p.Value=if($null-eq$x){[DBNull]::Value}else{[string]$x}}}
function Rows([string]$s,[object[]]$v=@()){$c=$null;$r=$null;try{$c=Conn;$q=$c.CreateCommand();$q.CommandText=$s;Params $q $v;$r=$q.ExecuteReader();$o=New-Object Collections.Generic.List[object];while($r.Read()){$h=[ordered]@{};for($i=0;$i-lt$r.FieldCount;$i++){$x=$r.GetValue($i);if($x-is[DBNull]){$x=$null};$h[$r.GetName($i)]=$x};$o.Add([pscustomobject]$h)};$o.ToArray()}finally{if($r){$r.Close();$r.Dispose()};if($c){$c.Close();$c.Dispose()}}}
function Scalar([string]$s,[object[]]$v=@()){$c=$null;try{$c=Conn;$q=$c.CreateCommand();$q.CommandText=$s;Params $q $v;$x=$q.ExecuteScalar();if($x-is[DBNull]){$null}else{$x}}finally{if($c){$c.Close();$c.Dispose()}}}
function Exec([string]$s,[object[]]$v=@()){$c=$null;try{$c=Conn;$q=$c.CreateCommand();$q.CommandText=$s;Params $q $v;$q.ExecuteNonQuery()}finally{if($c){$c.Close();$c.Dispose()}}}
function Common{Join-Path (Root) 'GameServer\Data\GameServerInfo - Common.dat'}
function Config{$h=[ordered]@{};if(Test-Path (Common)){foreach($l in Get-Content (Common)){if($l-match '^\s*([^;#/ \t=]+)\s*=\s*(.*?)\s*$'){$h[$matches[1]]=$matches[2]}}};[pscustomobject]$h}
function Backup([string]$f){if(Test-Path $f -PathType Leaf){$b="$f.panel-backup-$(Get-Date -Format yyyyMMdd-HHmmss)";Copy-Item $f $b -Force;$b}}
function SetCfg([string]$k,[string]$v){if($k-notmatch '^[A-Za-z0-9_]+$'-or$v-match '[\r\n]'){throw'Chave ou valor inválido'};$f=Common;Backup $f|Out-Null;$t=[IO.File]::ReadAllText($f);$p='(?m)^\s*'+[regex]::Escape($k)+'\s*=.*$';if([regex]::IsMatch($t,$p)){$t=[regex]::Replace($t,$p,$k+' = '+$v,1)}else{$t=$t.TrimEnd()+[Environment]::NewLine+$k+' = '+$v+[Environment]::NewLine};[IO.File]::WriteAllText($f,$t,(New-Object Text.UTF8Encoding($false)));Audit 'config.save' ($k+'='+$v)}
function FilePath([string]$rel){if(!$rel){throw'Arquivo não informado'};$r=[IO.Path]::GetFullPath((Root)).TrimEnd('\')+'\';$f=[IO.Path]::GetFullPath((Join-Path (Root) $rel.Replace('/','\')));if(!$f.StartsWith($r,[StringComparison]::OrdinalIgnoreCase)){throw'Caminho fora do servidor'};$ok=@('Data','GameServer\Data','GameServerCS\Data','JoinServer\Data','ConnectServer\Data','DataServer\Data')|%{[IO.Path]::GetFullPath((Join-Path (Root) $_)).TrimEnd('\')+'\'};if(!($ok|?{$f.StartsWith($_,[StringComparison]::OrdinalIgnoreCase)})){throw'Arquivo não permitido'};if([IO.Path]::GetExtension($f)-notin '.txt','.dat','.ini','.cfg','.xml'){throw'Extensão não permitida'};$f}
function Rel([string]$f){$f.Substring(([IO.Path]::GetFullPath((Root))).TrimEnd('\').Length+1).Replace('\','/')}
function Files{$o=New-Object Collections.Generic.List[object];foreach($d in 'Data\Event','Data\MonsterSetBase','Data\Util','Data\Custom','Data\Item','GameServer\Data'){$p=Join-Path (Root) $d;if(Test-Path $p){foreach($f in Get-ChildItem $p -File -Recurse|?{$_.Extension-in '.txt','.dat','.ini','.cfg','.xml'}){$o.Add([pscustomobject]@{path=Rel $f.FullName;name=$f.Name})}}};return @($o.ToArray()|sort path)}
function ToInt([string]$v,[int]$default=0){$n=0;if([int]::TryParse($v,[ref]$n)){$n}else{$default}}
function ItemMeta([int]$group,[int]$index,[string[]]$head,[string]$name,[string[]]$tail){
  $classNames=@('None','DW','DK','FE','MG','DL','SU','RF')
