  if(!$category){$category='Grupo '+$group}
  $m=[ordered]@{group=$group;index=$index;code=($group*512+$index);clientCode=('G{0} / índice {1}' -f $group,$index);codeKey=('G{0}:I{1}' -f $group,$index);name=$name;category=$category;typeName=$category;slotType=$(if($head.Count-gt 0){ToInt $head[0]}else{0});skillType=$(if($head.Count-gt 1){ToInt $head[1]}else{0});width=$(if($head.Count-gt 2){ToInt $head[2]}else{1});height=$(if($head.Count-gt 3){ToInt $head[3]}else{1});hasSerial=$(if($head.Count-gt 4){ToInt $head[4]}else{0});hasOption=$(if($head.Count-gt 5){ToInt $head[5]}else{0});dropItem=$(if($head.Count-gt 6){ToInt $head[6]}else{0});level=$(if($tail.Count-gt 0){ToInt $tail[0]}else{0});baseDurability=0;attackMin=0;attackMax=0;attackSpeed=0;magicDurability=0;magicDamageRate=0;defense=0;secondaryValue=0;secondaryLabel='';reqLevel=0;reqStrength=0;reqDexterity=0;reqEnergy=0;reqVitality=0;reqLeadership=0;buyMoney=0;value=0;classFlags=@()}
  $classStart=0
  if($group -le 5){$m.attackMin=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.attackMax=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.attackSpeed=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$m.baseDurability=if($tail.Count-gt 4){ToInt $tail[4]}else{0};$m.magicDurability=if($tail.Count-gt 5){ToInt $tail[5]}else{0};$m.magicDamageRate=if($tail.Count-gt 6){ToInt $tail[6]}else{0};$m.reqLevel=if($tail.Count-gt 7){ToInt $tail[7]}else{0};$m.reqStrength=if($tail.Count-gt 8){ToInt $tail[8]}else{0};$m.reqDexterity=if($tail.Count-gt 9){ToInt $tail[9]}else{0};$m.reqEnergy=if($tail.Count-gt 10){ToInt $tail[10]}else{0};$m.reqVitality=if($tail.Count-gt 11){ToInt $tail[11]}else{0};$m.reqLeadership=if($tail.Count-gt 12){ToInt $tail[12]}else{0};$classStart=13}
  elseif($group-eq6){$m.defense=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.secondaryValue=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.secondaryLabel='Taxa de sucesso de defesa';$m.baseDurability=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$m.reqLevel=if($tail.Count-gt 4){ToInt $tail[4]}else{0};$m.reqStrength=if($tail.Count-gt 5){ToInt $tail[5]}else{0};$m.reqDexterity=if($tail.Count-gt 6){ToInt $tail[6]}else{0};$m.reqEnergy=if($tail.Count-gt 7){ToInt $tail[7]}else{0};$m.reqVitality=if($tail.Count-gt 8){ToInt $tail[8]}else{0};$m.reqLeadership=if($tail.Count-gt 9){ToInt $tail[9]}else{0};$classStart=10}
  elseif($group-ge7-and$group-le9){$m.defense=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.secondaryValue=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.secondaryLabel='Defesa mágica';$m.baseDurability=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$m.reqLevel=if($tail.Count-gt 4){ToInt $tail[4]}else{0};$m.reqStrength=if($tail.Count-gt 5){ToInt $tail[5]}else{0};$m.reqDexterity=if($tail.Count-gt 6){ToInt $tail[6]}else{0};$m.reqEnergy=if($tail.Count-gt 7){ToInt $tail[7]}else{0};$m.reqVitality=if($tail.Count-gt 8){ToInt $tail[8]}else{0};$m.reqLeadership=if($tail.Count-gt 9){ToInt $tail[9]}else{0};$classStart=10}
  elseif($group-eq10){$m.defense=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.attackSpeed=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.secondaryLabel='Velocidade de ataque';$m.baseDurability=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$m.reqLevel=if($tail.Count-gt 4){ToInt $tail[4]}else{0};$m.reqStrength=if($tail.Count-gt 5){ToInt $tail[5]}else{0};$m.reqDexterity=if($tail.Count-gt 6){ToInt $tail[6]}else{0};$m.reqEnergy=if($tail.Count-gt 7){ToInt $tail[7]}else{0};$m.reqVitality=if($tail.Count-gt 8){ToInt $tail[8]}else{0};$m.reqLeadership=if($tail.Count-gt 9){ToInt $tail[9]}else{0};$classStart=10}
  elseif($group-eq11){$m.defense=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.attackSpeed=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.secondaryLabel='Velocidade de caminhada';$m.baseDurability=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$m.reqLevel=if($tail.Count-gt 4){ToInt $tail[4]}else{0};$m.reqStrength=if($tail.Count-gt 5){ToInt $tail[5]}else{0};$m.reqDexterity=if($tail.Count-gt 6){ToInt $tail[6]}else{0};$m.reqEnergy=if($tail.Count-gt 7){ToInt $tail[7]}else{0};$m.reqVitality=if($tail.Count-gt 8){ToInt $tail[8]}else{0};$m.reqLeadership=if($tail.Count-gt 9){ToInt $tail[9]}else{0};$classStart=10}
  elseif($group-eq12){$m.defense=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.baseDurability=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.reqLevel=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$m.reqEnergy=if($tail.Count-gt 4){ToInt $tail[4]}else{0};$m.reqStrength=if($tail.Count-gt 5){ToInt $tail[5]}else{0};$m.reqDexterity=if($tail.Count-gt 6){ToInt $tail[6]}else{0};$m.reqLeadership=if($tail.Count-gt 7){ToInt $tail[7]}else{0};$m.buyMoney=if($tail.Count-gt 8){ToInt $tail[8]}else{0};$classStart=9}
  elseif($group-eq13){$m.baseDurability=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$classStart=8}
  elseif($group-eq14){$m.value=if($tail.Count-gt 0){ToInt $tail[0]}else{0};$m.level=if($tail.Count-gt 1){ToInt $tail[1]}else{0}}
  elseif($group-eq15){$m.reqLevel=if($tail.Count-gt 1){ToInt $tail[1]}else{0};$m.reqEnergy=if($tail.Count-gt 2){ToInt $tail[2]}else{0};$m.buyMoney=if($tail.Count-gt 3){ToInt $tail[3]}else{0};$classStart=4}
  if($classStart -gt 0){$flags=New-Object Collections.Generic.List[string];foreach($n in 0..7){$ix=$classStart+$n;if($ix-lt$tail.Count-and(ToInt $tail[$ix]) -gt 0){$flags.Add($classNames[$n])}};$m.classFlags=$flags.ToArray()}
  $m.base=[pscustomobject]([ordered]@{category=$m.category;type=$m.typeName;slotType=$m.slotType;width=$m.width;height=$m.height;level=$m.level;attackMin=$m.attackMin;attackMax=$m.attackMax;attackSpeed=$m.attackSpeed;magicDurability=$m.magicDurability;magicDamageRate=$m.magicDamageRate;defense=$m.defense;secondaryValue=$m.secondaryValue;secondaryLabel=$m.secondaryLabel;baseDurability=$m.baseDurability;reqLevel=$m.reqLevel;reqStrength=$m.reqStrength;reqDexterity=$m.reqDexterity;reqEnergy=$m.reqEnergy;reqVitality=$m.reqVitality;reqLeadership=$m.reqLeadership;buyMoney=$m.buyMoney;value=$m.value})
  [pscustomobject]$m
}
function Items{$f=Join-Path (Root) 'Data\Item\Item.txt';if(!(Test-Path $f)){return @()};$g=-1;$o=New-Object Collections.Generic.List[object];foreach($l in Get-Content $f){if($l-match '^\s*(\d+)\s*$'){$g=[int]$matches[1];continue};$m=[regex]::Match($l,'^\s*(\d+)\s+(.*?)\s+"([^"]+)"\s+(.*)$');if($m.Success-and$g-ge 0){$head=@($m.Groups[2].Value.Trim()-split '\s+');$tail=@($m.Groups[4].Value.Trim()-split '\s+');$o.Add((ItemMeta $g ([int]$m.Groups[1].Value) $head $m.Groups[3].Value $tail))}};return $o.ToArray()}
function NormalizeHex([string]$h,[int]$bytes){if(!$h){$h=('F'*($bytes*2));};$h=$h.Replace(' ','').Replace("`r",'').Replace("`n",'').ToUpperInvariant();if($h-notmatch '^[0-9A-F]+$'-or$h.Length-ne($bytes*2)){throw 'Dados de item inválidos'};$h}
function ParseStorageSlot([string]$hex,[int]$slot,[string]$area,[object[]]$catalog){
  $chunk=$hex.Substring($slot*32,32);$empty=$chunk -match '^F{32}$';$kind=if($area-eq'inventory' -and $slot-lt 12){'Equipamento'}elseif($area-eq'inventory'){'Inventário'}else{'Baú principal'}
  if($empty){return [pscustomobject]@{slot=$slot;area=$area;empty=$true;kind=$kind;hex=$chunk;group=$null;index=$null;code=$null;clientCode=$null;codeKey=$null;name='Vazio';category=$null;typeName=$null;width=1;height=1;catalogLevel=0;base=$null;classFlags=@();level=0;skill=0;luck=0;option=0;excellent=0;ancient=0;refine=0;harmonyType=0;harmonyLevel=0;durability=0;serial='';sockets=@(255,255,255,255,255)}}
  $b1=[Convert]::ToInt32($chunk.Substring(2,2),16);$b7=[Convert]::ToInt32($chunk.Substring(14,2),16);$b8=[Convert]::ToInt32($chunk.Substring(16,2),16);$b9=[Convert]::ToInt32($chunk.Substring(18,2),16);$b10=[Convert]::ToInt32($chunk.Substring(20,2),16);$g=($b9 -shr 4)-band 15;$i=[Convert]::ToInt32($chunk.Substring(0,2),16);$x=@($catalog|?{$_.group-eq$g -and $_.index-eq$i}|select -First 1);$code=$g*512+$i;$clientCode=('G{0} / índice {1}' -f $g,$i);$base=if($x){$x.base}else{$null};$flags=if($x){$x.classFlags}else{@()}
  [pscustomobject]@{slot=$slot;area=$area;empty=$false;kind=$kind;hex=$chunk;group=$g;index=$i;code=$code;clientCode=$clientCode;codeKey=('G{0}:I{1}' -f $g,$i);name=if($x){$x.name}else{"Grupo $g / Índice $i"};category=if($x){$x.category}else{"Grupo $g"};typeName=if($x){$x.typeName}else{"Grupo $g"};width=if($x){$x.width}else{1};height=if($x){$x.height}else{1};catalogLevel=if($x){$x.level}else{0};base=$base;classFlags=$flags;level=($b1 -shr 3)-band 15;skill=if($b1-band 128){1}else{0};luck=if($b1-band 4){1}else{0};option=(($b1-band 3)+$(if($b7-band 64){4}else{0}));excellent=$b7-band 63;ancient=$b8-band 15;refine=$b9-band 15;harmonyType=($b10 -shr 4)-band 15;harmonyLevel=$b10-band 15;durability=[Convert]::ToInt32($chunk.Substring(4,2),16);serial=$chunk.Substring(6,8);sockets=@(0..4|%{[Convert]::ToInt32($chunk.Substring(22+($_*2),2),16)})}
}
function Storage([string]$account,[string]$character){if($account-notmatch '^[A-Za-z0-9_]{1,10}$'-or$character-notmatch '^[A-Za-z0-9_]{1,10}$'){throw 'Conta ou personagem inválido'};$c=@(Rows 'SELECT TOP 1 AccountID,Name,CONVERT(varchar(max),Inventory,2) AS InventoryHex FROM Character WHERE AccountID=? AND Name=?' @($account,$character))|select -First 1;if(!$c){throw 'Personagem não encontrado nessa conta'};$w=@(Rows 'SELECT TOP 1 AccountID,CONVERT(varchar(max),Items,2) AS WarehouseHex FROM warehouse WHERE AccountID=?' @($account))|select -First 1;$ih=NormalizeHex ([string]$c.InventoryHex) 4000;$wh=if($w){NormalizeHex ([string]$w.WarehouseHex) 3840}else{('F'*7680)};$cat=@(Items);$inv=New-Object Collections.Generic.List[object];$box=New-Object Collections.Generic.List[object];foreach($n in 0..249){$inv.Add((ParseStorageSlot $ih $n 'inventory' $cat))};foreach($n in 0..239){$box.Add((ParseStorageSlot $wh $n 'warehouse' $cat))};[pscustomobject]@{account=$account;character=$character;inventory=[pscustomobject]@{bytes=4000;slots=$inv.ToArray()};warehouse=[pscustomobject]@{bytes=3840;slots=$box.ToArray()}}}
function NewItemHex($b){$g=[int]$b.group;$i=[int]$b.index;$l=[int]$b.level;$skill=[int]$b.skill;$luck=[int]$b.luck;$op=[int]$b.option;$ex=[int]$b.excellent;$anc=[int]$b.ancient;$ref=[int]$b.refine;$ht=[int]$b.harmonyType;$hl=[int]$b.harmonyLevel;$dur=[int]$b.durability;if($g-lt 0-or$g-gt 15-or$i-lt 0-or$i-gt 255-or$l-lt 0-or$l-gt 15-or$op-lt 0-or$op-gt 7-or$ex-lt 0-or$ex-gt 63-or$anc-lt 0-or$anc-gt 15-or$ref-lt 0-or$ref-gt 15-or$ht-lt 0-or$ht-gt 15-or$hl-lt 0-or$hl-gt 15-or$dur-lt 0-or$dur-gt 255){throw 'Adicionais do item fora do limite'};$a=New-Object byte[] 16;$a[0]=[byte]$i;$a[1]=[byte]((($l-band 15)-shl 3)-bor $(if($skill){128}else{0})-bor $(if($luck){4}else{0})-bor($op-band 3));$a[2]=[byte]$dur;$serial=[BitConverter]::GetBytes([int][Environment]::TickCount);[Array]::Copy($serial,0,$a,3,4);$a[7]=[byte](($ex-band 63)-bor $(if($op-ge 4){64}else{0}));$a[8]=[byte]($anc-band 15);$a[9]=[byte](($g-shl 4)-bor($ref-band 15));$a[10]=[byte](($ht-shl 4)-bor($hl-band 15));foreach($n in 0..4){$v=[int]$b.('sock'+($n+1));if($v-lt 0-or$v-gt 255){$v=255};$a[11+$n]=[byte]$v};([BitConverter]::ToString($a)).Replace('-','')}
function UpdateStorageSlot($b,[string]$hex){$account=[string]$b.account;$character=[string]$b.character;$area=[string]$b.area;$slot=[int]$b.slot;if($account-notmatch '^[A-Za-z0-9_]{1,10}$'-or$character-notmatch '^[A-Za-z0-9_]{1,10}$'){throw 'Conta ou personagem inválido'};$owner=@(Rows 'SELECT TOP 1 AccountID FROM Character WHERE AccountID=? AND Name=?' @($account,$character))|select -First 1;if(!$owner){throw 'Personagem não encontrado nessa conta'};if($area-eq'inventory'){$limit=250;$old=[string](Scalar 'SELECT CONVERT(varchar(max),Inventory,2) FROM Character WHERE AccountID=? AND Name=?' @($account,$character));$old=NormalizeHex $old 4000;$table='Character';$where='AccountID=? AND Name=?';$values=@($account,$character);$column='Inventory'}elseif($area-eq'warehouse'){$limit=240;$old=[string](Scalar 'SELECT TOP 1 CONVERT(varchar(max),Items,2) FROM warehouse WHERE AccountID=?' @($account));$old=NormalizeHex $old 3840;$row=[int](Scalar 'SELECT COUNT(*) FROM warehouse WHERE AccountID=?' @($account));if(!$row){Exec 'INSERT INTO warehouse(AccountID,Items,Money) VALUES(?,CONVERT(varbinary(3840),0x'+('F'*7680)+'),0)' @($account)|Out-Null;$old=('F'*7680)};$table='warehouse';$where='AccountID=?';$values=@($account);$column='Items'}else{throw 'Área de armazenamento inválida'};if($slot-lt 0-or$slot-ge$limit){throw 'Slot fora do limite'};$new=$old.Substring(0,$slot*32)+$hex+$old.Substring(($slot+1)*32);$sql=if($area-eq'inventory'){'UPDATE Character SET Inventory=0x'+$new+' WHERE AccountID=? AND Name=?'}else{'UPDATE warehouse SET Items=0x'+$new+' WHERE AccountID=?'};$affected=Exec $sql $values;if($affected-lt 1){throw 'Nenhum registro foi atualizado'};Audit ('storage.'+$area) ($account+':'+$character+':slot'+$slot);[pscustomobject]@{affected=$affected;area=$area;slot=$slot;hex=$hex}}
function Procs{$o=New-Object Collections.Generic.List[object];foreach($n in 'ConnectServer','DataServer','JoinServer','GameServer','GameServerCS','Genesys StartUp'){$p=@(Get-Process $n -EA SilentlyContinue);$o.Add([pscustomobject]@{name=$n;running=$p.Count-gt 0;count=$p.Count})};return $o.ToArray()}
function Dash{$db=$false;$a=0;$c=0;$o=0;try{$a=[int](Scalar 'SELECT COUNT(*) FROM MEMB_INFO');$c=[int](Scalar 'SELECT COUNT(*) FROM Character');$o=[int](Scalar 'SELECT COUNT(*) FROM MEMB_STAT WHERE ConnectStat>0');$db=$true}catch{};$m=Config;[pscustomobject]@{profile=Profile;database=$db;counts=[pscustomobject]@{accounts=$a;characters=$c;online=$o};services=Procs;config=[pscustomobject]@{exp=$m.AddExperienceRate_AL0;master=$m.AddMasterExperienceRate_AL0;life=$m.MonsterLifeRate;item=$m.ItemDropRate_AL0;money=$m.MoneyAmountDropRate_AL0;max=$m.ServerMaxUserNumber;lock=$m.ServerLock;maint=$m.ServerMaintenance}}}
function ReadBody($c){$r=New-Object IO.StreamReader($c.Request.InputStream,$c.Request.ContentEncoding);try{$x=$r.ReadToEnd();if(!$x){[pscustomobject]@{}}else{$x|ConvertFrom-Json}}finally{$r.Dispose()}}
function SendJson($c,$x,[int]$status=200){$b=[Text.Encoding]::UTF8.GetBytes(($x|ConvertTo-Json -Depth 12 -Compress));$c.Response.StatusCode=$status;$c.Response.ContentType='application/json; charset=utf-8';$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}
function SendText($c,[string]$x,[string]$type='text/plain; charset=utf-8'){$b=[Text.Encoding]::UTF8.GetBytes($x);$c.Response.ContentType=$type;$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}
function AssetPath([string]$rel){if(!$rel){throw 'Asset não informado'};$r=[IO.Path]::GetFullPath((Join-Path $ClientRoot 'Data')).TrimEnd('\')+'\';$f=[IO.Path]::GetFullPath((Join-Path $ClientRoot ($rel.Replace('/','\'))));if(!$f.StartsWith($r,[StringComparison]::OrdinalIgnoreCase)){throw 'Asset fora da pasta Data'};$ext=[IO.Path]::GetExtension($f).ToLowerInvariant();if($ext -notin '.jpg','.jpeg','.png','.gif','.bmp','.ozj'){throw 'Tipo de asset não permitido'};if(!(Test-Path $f -PathType Leaf)){throw 'Asset não encontrado'};$f}
function SendAsset($c,[string]$rel){$f=AssetPath $rel;$b=[IO.File]::ReadAllBytes($f);$ext=[IO.Path]::GetExtension($f).ToLowerInvariant();if($ext-eq'.ozj' -and $b.Length-gt 24){$jpeg=New-Object byte[] ($b.Length-24);[Array]::Copy($b,24,$jpeg,0,$jpeg.Length);$b=$jpeg};$type=@{'.jpg'='image/jpeg';'.jpeg'='image/jpeg';'.ozj'='image/jpeg';'.png'='image/png';'.gif'='image/gif';'.bmp'='image/bmp'}[$ext];$c.Response.ContentType=$type;$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}
function Q($c,[string]$n){[string]$c.Request.QueryString[$n]}
function SearchChar([string]$q){if(!$q){return @()};@(Rows 'SELECT TOP 100 Name,AccountID,cLevel,Experience,Money,ResetCount,MasterResetCount,MapNumber FROM Character WHERE Name LIKE ? OR AccountID LIKE ? ORDER BY Name' @("%$q%","%$q%"))}
function SearchAccount([string]$q){if(!$q){return @()};@(Rows 'SELECT TOP 100 i.memb___id AS AccountID,i.memb_name AS AccountName,i.AccountLevel,i.Lock AS AccountLock,s.ConnectStat,ISNULL(x.CharCount,0) AS CharCount FROM MEMB_INFO i LEFT JOIN MEMB_STAT s ON s.memb___id=i.memb___id LEFT JOIN (SELECT AccountID,COUNT(*) CharCount FROM Character GROUP BY AccountID) x ON x.AccountID=i.memb___id WHERE i.memb___id LIKE ? OR i.memb_name LIKE ? ORDER BY i.memb___id' @("%$q%","%$q%"))}
function CharOne([string]$n){@(Rows 'SELECT TOP 1 Name,AccountID,cLevel,Experience,Strength,Dexterity,Vitality,Energy,Leadership,Money,ResetCount,MasterResetCount,MapNumber,MapPosX,MapPosY,PKLevel,CtlCode,LevelUpPoint,FruitPoint FROM Character WHERE Name=?' @($n))|select -First 1}
function AccOne([string]$id){$a=@(Rows 'SELECT TOP 1 memb___id AS AccountID,memb_name AS AccountName,AccountLevel,Lock AS AccountLock,BlocChat FROM MEMB_INFO WHERE memb___id=?' @($id))|select -First 1;if($a){$c=@(Rows 'SELECT TOP 1 AccountID,WCoinC,WCoinP,GoblinPoint FROM CashShopData WHERE AccountID=?' @($id))|select -First 1;$a|Add-Member Coins $c -Force};$a}
function Online{@(Rows 'SELECT TOP 100 s.memb___id AS AccountID,s.ServerName,c.Name,c.cLevel,c.MapNumber FROM MEMB_STAT s LEFT JOIN Character c ON c.AccountID=s.memb___id WHERE s.ConnectStat>0 ORDER BY c.Name')}
function DoAction($b){switch([string]$b.action){
 'character.save'{$n=[string]$b.Name;if($n-notmatch '^[A-Za-z0-9_]{1,10}$'){throw'Nome inválido'};$x=Exec 'UPDATE Character SET AccountID=?,cLevel=?,Experience=?,Strength=?,Dexterity=?,Vitality=?,Energy=?,Leadership=?,Money=?,ResetCount=?,MasterResetCount=?,MapNumber=?,MapPosX=?,MapPosY=?,PKLevel=?,CtlCode=?,LevelUpPoint=?,FruitPoint=? WHERE Name=?' @($b.AccountID,$b.cLevel,$b.Experience,$b.Strength,$b.Dexterity,$b.Vitality,$b.Energy,$b.Leadership,$b.Money,$b.ResetCount,$b.MasterResetCount,$b.MapNumber,$b.MapPosX,$b.MapPosY,$b.PKLevel,$b.CtlCode,$b.LevelUpPoint,$b.FruitPoint,$n);Audit 'character.save' $n;[pscustomobject]@{affected=$x}}
 'character.create'{$n=[string]$b.Name;$id=[string]$b.AccountID;if($n-notmatch '^[A-Za-z0-9_]{1,10}$'){throw 'Nome inválido'};if($id-notmatch '^[A-Za-z0-9_]{1,10}$'){throw 'Conta inválida'};if([int](Scalar 'SELECT COUNT(*) FROM MEMB_INFO WHERE memb___id=?' @($id))-eq 0){throw 'Conta não encontrada'};if([int](Scalar 'SELECT COUNT(*) FROM Character WHERE Name=?' @($n))-gt 0){throw 'Personagem já existe'};$x=Exec 'INSERT INTO Character(AccountID,Name,cLevel,Class,Experience,Strength,Dexterity,Vitality,Energy,Leadership,Money,MapNumber,MapPosX,MapPosY,PkLevel,CtlCode,LevelUpPoint,FruitPoint,ResetCount,MasterResetCount) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)' @($id,$n,$b.cLevel,$b.Class,$b.Experience,$b.Strength,$b.Dexterity,$b.Vitality,$b.Energy,$b.Leadership,$b.Money,$b.MapNumber,$b.MapPosX,$b.MapPosY,$b.PKLevel,$b.CtlCode,$b.LevelUpPoint,$b.FruitPoint,$b.ResetCount,$b.MasterResetCount);Audit 'character.create' ($id+':'+$n);[pscustomobject]@{created=$true;name=$n;affected=$x}}
   'character.reset'{$x=Exec 'UPDATE Character SET Strength=0,Dexterity=0,Vitality=0,Energy=0,Leadership=0,LevelUpPoint=0,FruitPoint=0 WHERE Name=?' @([string]$b.Name);Audit 'character.reset' $b.Name;[pscustomobject]@{affected=$x}}
   'storage.save'{$h=NewItemHex $b;UpdateStorageSlot $b $h}
   'storage.clear'{$h='F'*32;UpdateStorageSlot $b $h}
 'account.save'{$id=[string]$b.AccountID;if($id-notmatch '^[A-Za-z0-9_]{1,10}$'){throw'Login inválido'};$x=Exec 'UPDATE MEMB_INFO SET AccountLevel=?,Lock=?,BlocChat=? WHERE memb___id=?' @($b.AccountLevel,$b.tLock,$b.tBloc_chat,$id);Exec 'IF EXISTS(SELECT 1 FROM CashShopData WHERE AccountID=?) UPDATE CashShopData SET WCoinC=?,WCoinP=?,GoblinPoint=? WHERE AccountID=? ELSE INSERT INTO CashShopData(AccountID,WCoinC,WCoinP,GoblinPoint) VALUES(?,?,?,?)' @($id,$b.tWCoinC,$b.tWCoinP,$b.tGoblinPoint,$id,$id,$b.tWCoinC,$b.tWCoinP,$b.tGoblinPoint)|Out-Null;Audit 'account.save' $id;[pscustomobject]@{affected=$x}}
 'account.password'{$id=[string]$b.AccountID;$p=[string]$b.Password;if($id-notmatch '^[A-Za-z0-9_]{1,10}$'-or$p.Length-lt 4){throw'Login ou senha inválida'};$x=Exec 'UPDATE MEMB_INFO SET memb__pwd=? WHERE memb___id=?' @($p,$id);Audit 'account.password' $id;[pscustomobject]@{affected=$x}}
 'config.save'{foreach($e in @($b.values)){if($e.key){SetCfg $e.key $e.value}};[pscustomobject]@{saved=$true}}
 'file.save'{$f=FilePath $b.path;Backup $f|Out-Null;[IO.File]::WriteAllText($f,$b.content,(New-Object Text.UTF8Encoding($false)));Audit 'file.save' $b.path;[pscustomobject]@{saved=$true}}
 'backup.create'{$d=Join-Path $Base ('backups\'+(Get-Date -Format yyyyMMdd-HHmmss));New-Item -ItemType Directory -Path $d -Force|Out-Null;foreach($r in 'GameServer\Data\GameServerInfo - Common.dat','Data\Util\ExperienceTable.txt','Data\Util\ResetTable.txt','Data\MonsterSetBase','Data\Event','Data\Item'){$s=Join-Path (Root) $r;if(Test-Path $s){Copy-Item $s $d -Recurse -Force}};Audit 'backup.create' $d;[pscustomobject]@{path=$d}}
 default{throw'Ação desconhecida'}
}}

