1b21 72%);color:#bdcdcd;cursor:pointer;text-align:center}.game-slot:hover,.game-slot.active{border-color:#e7cc72;box-shadow:0 0 0 1px #b69742,0 0 14px #e5c96b55}.game-slot.empty{opacity:.72}.game-slot .slotno{display:block;font-size:9px;color:#829a9d}.game-slot .art{display:grid;place-items:center;height:34px;font-size:24px;text-shadow:0 2px 5px #000}.game-slot .art.wing{background:url('/asset?path=Data/Item/Fifth_Dknight_Wing_01_c.jpg') center/contain no-repeat;font-size:0}.game-slot .item-short{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:9px;color:#e1eded}.game-slot .level{position:absolute;top:2px;right:3px;color:#f6da7d;font-size:10px;font-weight:700}.game-slot .empty-mark{font-size:19px;color:#557077;line-height:34px}.game-grid{display:grid;grid-template-columns:repeat(8,minmax(37px,1fr));gap:4px;padding:8px;border-radius:8px;background:repeating-linear-gradient(0deg,#0b151bdd,#0b151bdd 44px,#26383ddf 45px),repeating-linear-gradient(90deg,transparent,transparent 44px,#26383d 45px);max-height:365px;overflow:auto}.game-grid.warehouse{grid-template-columns:repeat(8,minmax(37px,1fr));max-height:455px}.game-grid .game-slot{min-height:52px}.game-tooltip{position:fixed;display:none;z-index:50;min-width:245px;max-width:315px;padding:10px 12px;border:1px solid #a88743;border-radius:7px;background:linear-gradient(165deg,#101419f8,#030506f8);box-shadow:0 8px 25px #000b;color:#e6eded;font:12px Segoe UI,Arial;pointer-events:none}.game-tooltip.show{display:block}.game-tooltip .tip-name{color:#f2d36f;font-size:14px;font-weight:700;margin-bottom:6px}.game-tooltip .tip-meta{color:#a9c8ca;font-size:11px;margin-bottom:6px}.game-tooltip .tip-line{display:flex;justify-content:space-between;gap:16px;border-top:1px solid #ffffff14;padding:3px 0}.game-tooltip .tip-line b{color:#e8f0ef;font-weight:500;text-align:right}.game-editor-note{margin-top:10px;padding:9px;border-radius:7px;background:#0a161ce6;color:#a6c8c6;font-size:11px}.game-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.game-actions button{border:1px solid #729392;border-radius:7px;background:#173640;color:#f2f7f6;padding:7px 9px;cursor:pointer}.game-actions button:hover{border-color:#eed27a;color:#ffe49b}.game-storage .game-panel::-webkit-scrollbar,.game-grid::-webkit-scrollbar{width:8px}.game-storage .game-panel::-webkit-scrollbar-thumb,.game-grid::-webkit-scrollbar-thumb{background:#45696d;border-radius:8px}.game-badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#244d54;color:#b5e0d8;font-size:10px}@media(max-width:1250px){.game-storage{grid-template-columns:210px 1fr}.game-storage .game-right{grid-column:1/-1}.game-grid.warehouse{max-height:290px}}@media(max-width:780px){.game-storage{grid-template-columns:1fr}.game-storage .game-right{grid-column:auto}.game-grid,.game-grid.warehouse{grid-template-columns:repeat(6,minmax(36px,1fr))}.game-equip{grid-template-columns:repeat(4,1fr)}}
