$EnhancementJs=@'
function gameArt(x){var icons=['⚔','🛡','🏹','杖','🪓','♜','💍','🪽','♞','◆','◈','✦','✹','♜','⚔','✧'],files={0:'Item_Weapon01.OZJ',1:'Item_Weapon01.OZJ',2:'Item_Weapon02.OZJ',3:'Item_Weapon02.OZJ',4:'Item_Weapon02.OZJ',5:'Item_Weapon01.OZJ',7:'Item_Cap.OZJ',8:'Item_Upper.OZJ',9:'Item_Lower.OZJ',10:'Item_Gloves.OZJ',11:'Item_Boots.OZJ',12:'Item_Wing.OZJ',13:'Item_Ring.OZJ',14:'Item_Money.OZJ'},f=files[Number(x&&x.group)];return f?'<span class="art asset" style="background-image:url(\'/asset?path=Data/Interface/HUD/Look-1/'+f+'\')"></span>':'<span class="art">'+(x&&icons[Number(x.group)]||'✦')+'</span>'}
function gameItemName(x){return x&&!x.empty?esc(x.name)+(Number(x.level)>0?' +'+x.level:''):'Vazio'}
function tipLine(label,value){return '<div class="tip-line"><span>'+esc(label)+'</span><b>'+esc(String(value))+'</b></div>'}
function gameOriginalLines(x){var b=x.base||{},r=[],add=function(label,value){if(value!==undefined&&value!==null&&String(value)!=='')r.push(tipLine(label,value))};var g=Number(x.group);if(g<=5){add(g===5?'Ataque de uma mão (base)':'Ataque físico (base)',(Number(b.attackMin)||0)+' ~ '+(Number(b.attackMax)||0));if(g===5){if(Number(b.magicDurability)>0)add('Poder mágico (base)',b.magicDurability);if(Number(b.magicDamageRate)>0)add('Taxa mágica',b.magicDamageRate+'%')}if(Number(b.attackSpeed)>0)add('Velocidade de ataque',b.attackSpeed);if(Number(b.baseDurability)>0)add('Durabilidade original',b.baseDurability)}else if(g===6){add('Defesa (base)',b.defense);if(Number(b.secondaryValue)>0)add(b.secondaryLabel,b.secondaryValue);add('Durabilidade original',b.baseDurability)}else if(g>=7&&g<=11){add('Defesa (base)',b.defense);if(Number(b.secondaryValue)>0)add(b.secondaryLabel,b.secondaryValue);add('Durabilidade original',b.baseDurability)}else if(g===12){add('Defesa (base)',b.defense);add('Durabilidade original',b.baseDurability)}else if(g===13){add('Durabilidade original',b.baseDurability)}else if(g===14){add('Valor original',b.value);add('Nível do consumível',b.level)}else if(g===15){if(Number(b.reqLevel)>0)add('Requisito de nível',b.reqLevel);if(Number(b.reqEnergy)>0)add('Requisito de energia',b.reqEnergy);if(Number(b.buyMoney)>0)add('Preço base',b.buyMoney)}if(Number(b.reqLevel)>0&&g!==14&&g!==15)add('Requisito de nível',b.reqLevel);var req=[];if(Number(b.reqStrength)>0)req.push('Força '+b.reqStrength);if(Number(b.reqDexterity)>0)req.push('Agilidade '+b.reqDexterity);if(Number(b.reqEnergy)>0&&g!==15)req.push('Energia '+b.reqEnergy);if(Number(b.reqVitality)>0)req.push('Vitalidade '+b.reqVitality);if(Number(b.reqLeadership)>0)req.push('Comando '+b.reqLeadership);if(req.length)add('Requisitos',req.join(' • '));var cf=Array.isArray(x.classFlags)?x.classFlags:(x.classFlags?[x.classFlags]:[]);if(cf.length)add('Classes',cf.join(' • '));return r.join('')}
function gameOptionLines(x){var r=[];if(x.skill)r.push(tipLine('Habilidade','Disponível'));if(x.luck)r.push(tipLine('Sorte','Joia da Alma +25% • Crítico +5%'));if(Number(x.option)>0)r.push(tipLine(Number(x.group)>=7&&Number(x.group)<=11?'Defesa adicional':'Dano adicional','+'+(Number(x.option)*4)));if(Number(x.excellent)>0){var bits=[];for(var i=0;i<6;i++){if(Number(x.excellent)&(1<<i))bits.push('bit '+i)}r.push(tipLine('Excellent bits',bits.join(', ')+' • valor '+x.excellent))}if(Number(x.ancient)>0)r.push(tipLine('Ancient bruto',x.ancient+' (mantido do item)'));if(Number(x.refine)>0)r.push(tipLine('Refine',x.refine));if(Number(x.harmonyType)>0||Number(x.harmonyLevel)>0)r.push(tipLine('Harmony',x.harmonyType+' / '+x.harmonyLevel));return r.join('')}
function gameTipHtml(x,area){if(!x||x.empty)return '';var sockets=(x.sockets||[]).map(function(v){return Number(v)===255?'—':v}).join(' / ');return '<div class="tip-name">'+gameItemName(x)+'</div><div class="tip-meta">'+esc(x.kind)+' • '+(area==='inventory'?'Inventário':'Baú principal')+' • slot '+x.slot+'</div>'+tipLine('Código original',x.clientCode||('G'+x.group+' / índice '+x.index))+tipLine('ID composto MU',x.code)+tipLine('Categoria',x.typeName||x.category||'—')+tipLine('Tamanho',((x.width||1)+' × '+(x.height||1)))+gameOriginalLines(x)+tipLine('Durabilidade atual',x.durability+' / 255')+tipLine('Skill / Luck',(x.skill?'Sim':'Não')+' / '+(x.luck?'Sim':'Não'))+tipLine('Opção bruta',x.option)+gameOptionLines(x)+tipLine('Sockets',sockets)+'<div class="tip-meta" style="margin:6px 0 0">Serial: '+esc(x.serial||'—')+'</div><div class="tip-meta" style="margin:6px 0 0;color:#d8c98f">Somente leitura: atributos originais do Item.txt</div>'}
function moveGameTip(e){var t=$('gameTooltip');if(!t||!t.classList.contains('show'))return;var pad=16,x=e.clientX+pad,y=e.clientY+pad;if(x+t.offsetWidth>window.innerWidth-8)x=e.clientX-t.offsetWidth-pad;if(y+t.offsetHeight>window.innerHeight-8)y=e.clientY-t.offsetHeight-pad;t.style.left=Math.max(8,x)+'px';t.style.top=Math.max(8,y)+'px'}
function showGameTip(e,el){var area=el.dataset.area,slot=Number(el.dataset.slot),d=S.storage&&S.storage[area==='inventory'?'inventory':'warehouse'],x=d&&d.slots[slot],t=$('gameTooltip');if(!t||!x||x.empty){hideGameTip();return}t.innerHTML=gameTipHtml(x,area);t.classList.add('show');moveGameTip(e)}
function hideGameTip(){$('gameTooltip')&&$('gameTooltip').classList.remove('show')}
function gameSlot(x,area){var empty=!x||x.empty,active=S.bagArea===area&&S.bagSlot===x.slot;return '<button class="game-slot '+(empty?'empty ':'')+(active?'active':'')+'" data-area="'+area+'" data-slot="'+x.slot+'" onmouseenter="showGameTip(event,this)" onmousemove="moveGameTip(event)" onmouseleave="hideGameTip()" onclick="selectStorageSlot(this.dataset.area,Number(this.dataset.slot))"><span class="slotno">#'+x.slot+'</span>'+(empty?'<span class="empty-mark">＋</span>':gameArt(x)+'<span class="item-short">'+esc(x.name)+'</span><span class="level">'+(x.level?'+'+x.level:'')+'</span>')+'</button>'}
function ensureGameStorage(){if($('gameStorage'))return;var old=document.querySelector('#bag .storage-layout');if(!old)return;var node=document.createElement('div');node.id='gameStorage';node.className='game-storage';node.innerHTML='<div class="game-panel game-left"><h3>Menu administrativo</h3><div class="sub">Conta e personagem selecionados</div><div class="game-character"><strong id="gameCharName">—</strong><span id="gameCharMeta">Nenhum personagem</span></div><div class="game-stat"><span>Conta</span><b id="gameAccount">—</b></div><div class="game-stat"><span>Inventário</span><b id="gameInvCount">—</b></div><div class="game-stat"><span>Baú principal</span><b id="gameBoxCount">—</b></div><div class="game-character-list" id="gameCharList"><div class="sub">Selecione uma conta acima.</div></div><div class="game-editor-note">Passe o mouse em qualquer item para ver nível, durabilidade, skill, luck, excelente, ancient, harmony, sockets e serial. Clique para editar no formulário abaixo.</div></div><div class="game-panel"><div class="game-titlebar"><b>Inventário do personagem</b><span class="game-badge" id="gameInvBadge">—</span></div><div class="sub" style="display:block;margin-bottom:7px">Equipamento</div><div id="gameEquip" class="game-equip"></div><div class="sub" style="display:block;margin:7px 0">Mochila</div><div id="gameInventoryGrid" class="game-grid"></div><div class="game-actions"><button onclick="selectStorageSlot(\'inventory\',0)">Ir para equipamento</button><button onclick="selectStorageSlot(\'inventory\',12)">Ir para mochila</button></div></div><div class="game-panel game-right"><div class="game-titlebar"><b>Baú principal</b><span class="game-badge" id="gameBoxBadge">—</span></div><div class="sub" style="display:block;margin-bottom:7px">Armazenamento da conta em tempo real</div><div id="gameWarehouseGrid" class="game-grid warehouse"></div><div class="game-editor-note">A atualização automática ocorre a cada 5 segundos. Para salvar inventário equipado, deixe o personagem offline.</div></div>';old.parentNode.insertBefore(node,old);old.style.display='none';var tip=document.createElement('div');tip.id='gameTooltip';tip.className='game-tooltip';document.body.appendChild(tip)}
function renderGameStorage(){ensureGameStorage();if(!S.storage)return;var inv=S.storage.inventory,box=S.storage.warehouse,fi=inv.slots.filter(function(x){return!x.empty}).length,fb=box.slots.filter(function(x){return!x.empty}).length;$('gameCharName').textContent=S.storage.character||'—';$('gameCharMeta').textContent='Painel SQL • atualização automática';$('gameAccount').textContent=S.storage.account||'—';$('gameInvCount').textContent=fi+' / '+inv.slots.length;$('gameBoxCount').textContent=fb+' / '+box.slots.length;$('gameInvBadge').textContent=fi+' ocupados';$('gameBoxBadge').textContent=fb+' ocupados';$('gameEquip').innerHTML=inv.slots.slice(0,12).map(function(x){return gameSlot(x,'inventory')}).join('');$('gameInventoryGrid').innerHTML=inv.slots.slice(12).map(function(x){return gameSlot(x,'inventory')}).join('');$('gameWarehouseGrid').innerHTML=box.slots.map(function(x){return gameSlot(x,'warehouse')}).join('')}
function renderGameChars(rows){var e=$('gameCharList');if(!e)return;e.innerHTML=(rows||[]).map(function(x){return '<button onclick="pickGameChar(\''+esc(x.Name)+'\')"><b>'+esc(x.Name)+'</b><br><span class="sub">Nível '+esc(x.cLevel)+' • mapa '+esc(x.MapNumber)+'</span></button>'}).join('')||'<div class="sub">Nenhum personagem nessa conta.</div>'}
function pickGameChar(name){$('bagChar').value=name;loadStorage()}
var gameOriginalRenderExamples=window.renderBagExamples;window.renderBagExamples=function(){if(!$('bagItemExamples'))return;var q=($('bagItemSearch').value||'').toLowerCase();var a=S.items.filter(function(x){return(x.name+' '+x.code+' '+(x.clientCode||'')+' '+x.group+' '+x.index).toLowerCase().indexOf(q)>=0}).slice(0,120);$('bagItemExamples').innerHTML=a.map(function(x){return'<button class="itemtile" onclick="chooseBagItem('+x.group+','+x.index+')">'+gameArt(x)+'<b title="'+esc(x.name)+'">'+esc(x.name)+'</b><small>'+esc(x.clientCode||('G'+x.group+' / índice '+x.index))+' • ID '+esc(x.code)+' • Nv '+esc(x.level)+'</small></button>'}).join('')||'<div class="empty">Nenhum item encontrado.</div>'}
var gameOriginalChooseBagItem=window.chooseBagItem;window.chooseBagItem=function(g,i){gameOriginalChooseBagItem(g,i);var x=S.items.find(function(y){return y.group===Number(g)&&y.index===Number(i)});if(x)$('bagItemLabel').innerHTML='<b>'+esc(x.name)+'</b><small>'+esc(x.category||x.typeName||'Item')+' • '+esc(x.clientCode||('G'+x.group+' / índice '+x.index))+' • ID composto '+esc(x.code)+' • nível máximo '+esc(x.level)+'</small>'}
var gameOriginalSelectStorageSlot=window.selectStorageSlot;window.selectStorageSlot=function(area,slot){gameOriginalSelectStorageSlot(area,slot);var d=S.storage&&S.storage[area==='inventory'?'inventory':'warehouse'],x=d&&d.slots[Number(slot)];if(x&&!x.empty)$('bagItemLabel').innerHTML='<b>'+esc(x.name)+(Number(x.level)>0?' +'+x.level:'')+'</b><small>'+esc(x.typeName||x.category||x.kind)+' • '+esc(x.clientCode||('G'+x.group+' / índice '+x.index))+' • ID composto '+esc(x.code)+' • serial '+esc(x.serial||'—')+'</small>'}
var gameOriginalRenderStorage=window.renderStorage;window.renderStorage=function(){gameOriginalRenderStorage();renderGameStorage()};
var gameOriginalLoadBagChars=window.loadBagChars;window.loadBagChars=function(){var account=$('bagAcc').value;return gameOriginalLoadBagChars().then(function(result){if(!account){renderGameChars([]);return result}return api('/api/characters?q='+encodeURIComponent(account)).then(function(j){renderGameChars((j.rows||[]).filter(function(x){return x.AccountID===account}));return result})})};
function ensureAdvancedItemEditor(){if($('bagAdvanced'))return;var label=$('bagItemLabel'),card=label&&label.parentElement;if(!card)return;var style=document.createElement('style');style.textContent='.advanced-editor{margin-top:12px;padding:12px;border:1px solid #c9dadd;border-radius:10px;background:linear-gradient(145deg,#f7fbfb,#eef5f5)}.advanced-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:9px}.advanced-head h3{margin:0;font-size:14px;color:#20343a}.advanced-head label{font-size:11px;color:#35666c;display:flex;gap:6px;align-items:center}.advanced-head input{accent-color:#456f76}.advanced-grid{display:grid;grid-template-columns:1.25fr 1fr;gap:10px}.advanced-box{padding:9px;border:1px solid #d1e0e2;border-radius:8px;background:#fff}.advanced-box h4{margin:0 0 7px;color:#456f76;font-size:11px;text-transform:uppercase;letter-spacing:.5px}.excellent-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:5px}.excellent-grid label{display:flex;gap:6px;align-items:center;font-size:11px;color:#264149}.excellent-grid input{accent-color:#456f76}.socket-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.socket-grid select{min-width:0;padding:7px 3px;font-size:11px}.advanced-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.advanced-actions button{padding:7px 10px;border-radius:7px;border:1px solid #b7ced0;background:#fff;color:#315d64;cursor:pointer}.advanced-actions button.primary-adv{background:#456f76;border-color:#456f76;color:#fff}.advanced-actions button:hover{border-color:#e0b94f}.advanced-hint{margin-top:7px;color:#70868b;font-size:10px}@media(max-width:720px){.advanced-grid{grid-template-columns:1fr}.socket-grid{grid-template-columns:repeat(3,1fr)}}';document.head.appendChild(style);var box=document.createElement('div');box.id='bagAdvanced';box.className='advanced-editor';box.innerHTML='<div class="advanced-head"><h3>Opções avançadas do item</h3><label><input id="bagAutoSave" type="checkbox" checked> Aplicar alterações automaticamente</label></div><div class="advanced-grid"><div class="advanced-box"><h4>Excellent (bits 0–5)</h4><div class="excellent-grid"><label><input type="checkbox" data-exc="0"> Aumento de dano</label><label><input type="checkbox" data-exc="1"> Dano excelente</label><label><input type="checkbox" data-exc="2"> Dano adicional</label><label><input type="checkbox" data-exc="3"> Defesa adicional</label><label><input type="checkbox" data-exc="4"> Vida após caça</label><label><input type="checkbox" data-exc="5"> Mana após caça</label></div><div class="advanced-actions"><button onclick="setExcellentPreset(63)">Todas</button><button onclick="setExcellentPreset(0)">Limpar</button></div></div><div class="advanced-box"><h4>Ancient</h4><select id="bagAncientPreset"><option value="0">0 — Sem ancient</option><option value="1">1 — Ancient A</option><option value="2">2 — Ancient B</option><option value="3">3 — Ancient A + B</option><option value="custom">Personalizado</option></select><div class="advanced-hint">O valor numérico continua disponível no campo Ancient acima.</div><h4 style="margin-top:10px">Aplicação</h4><div class="advanced-hint">Altere os campos, opções e sockets. Com o automático ligado, cada alteração válida é gravada no slot selecionado.</div></div></div><div class="advanced-box" style="margin-top:10px"><h4>Sockets (valor real gravado)</h4><div class="socket-grid">'+[1,2,3,4,5].map(function(n){return '<select id="bagSockPreset'+n+'" data-sock="'+n+'"><option value="255">S'+n+' — vazio</option>'+Array.from({length:16},function(_,i){return '<option value="'+i+'">S'+n+' — valor '+i+'</option>'}).join('')+'</select>'}).join('')+'</div><div class="advanced-hint">255 representa socket vazio. Para valores especiais, use os campos Socket 1–5 do editor principal.</div></div><div class="advanced-actions"><button class="primary-adv" onclick="saveBagItem()">Aplicar agora no servidor</button><button onclick="setAncientPreset(3)">Ancient A + B</button><button onclick="clearAdvancedSockets()">Limpar sockets</button></div>';card.insertBefore(box,card.querySelector('.actions'));box.querySelectorAll('[data-exc]').forEach(function(e){e.addEventListener('change',function(){syncExcellentFields();queueBagAutoSave()})});box.querySelector('#bagAncientPreset').addEventListener('change',function(){setAncientPreset(this.value);queueBagAutoSave()});box.querySelectorAll('[data-sock]').forEach(function(e){e.addEventListener('change',function(){var n=e.dataset.sock;$('bagSock'+n).value=e.value;queueBagAutoSave()})})}
function syncAdvancedFields(){if(!$('bagAdvanced'))return;var ex=Number($('bagExcellent').value)||0;$('bagAdvanced').querySelectorAll('[data-exc]').forEach(function(e){e.checked=!!(ex&(1<<Number(e.dataset.exc)))});var av=String($('bagAncient').value||0),ap=$('bagAncientPreset');ap.value=['0','1','2','3'].indexOf(av)>=0?av:'custom';[1,2,3,4,5].forEach(function(n){var s=$('bagSockPreset'+n),v=String($('bagSock'+n).value||255);if(s)s.value=Array.from(s.options).some(function(o){return o.value===v})?v:'255'})}
function syncExcellentFields(){var ex=0;$('bagAdvanced').querySelectorAll('[data-exc]').forEach(function(e){if(e.checked)ex|=1<<Number(e.dataset.exc)});$('bagExcellent').value=ex}
function setExcellentPreset(v){$('bagExcellent').value=Number(v);syncAdvancedFields();queueBagAutoSave()}
function setAncientPreset(v){if(v==='custom')return;$('bagAncient').value=Number(v);syncAdvancedFields()}
function clearAdvancedSockets(){[1,2,3,4,5].forEach(function(n){$('bagSock'+n).value=255});syncAdvancedFields();queueBagAutoSave()}
var bagSaveTimer=null;function queueBagAutoSave(){if(!$('bagAutoSave')||!$('bagAutoSave').checked||!$('bagAcc').value||!$('bagChar').value||$('bagGroup').value===''||$('bagIndex').value==='')return;clearTimeout(bagSaveTimer);bagSaveTimer=setTimeout(function(){saveBagItem()},350)}
var gameOriginalSelectStorageSlot=window.selectStorageSlot;window.selectStorageSlot=function(){gameOriginalSelectStorageSlot.apply(this,arguments);ensureAdvancedItemEditor();setTimeout(syncAdvancedFields,0)};
var gameOriginalChooseBagItem=window.chooseBagItem;window.chooseBagItem=function(){gameOriginalChooseBagItem.apply(this,arguments);ensureAdvancedItemEditor();syncAdvancedFields()};
var gameOriginalRenderGameStorage=window.renderGameStorage;window.renderGameStorage=function(){gameOriginalRenderGameStorage();ensureAdvancedItemEditor();syncAdvancedFields()};
function bindBagAutoSaveFields(){var box=$('bagAdvanced');if(!box||box.dataset.bagBound)return;box.dataset.bagBound='1';['bagGroup','bagIndex','bagLevel','bagSkill','bagLuck','bagOption','bagExcellent','bagAncient','bagRefine','bagDurability','bagHarmonyType','bagHarmonyLevel','bagSock1','bagSock2','bagSock3','bagSock4','bagSock5'].forEach(function(id){var e=$(id);if(e)e.addEventListener('change',function(){syncAdvancedFields();queueBagAutoSave()})})}
var gameOriginalEnsureAdvanced=window.ensureAdvancedItemEditor;window.ensureAdvancedItemEditor=function(){gameOriginalEnsureAdvanced();bindBagAutoSaveFields()};
setTimeout(function(){ensureGameStorage();ensureAdvancedItemEditor()},0);
