background:var(--card);border:1px solid var(--line);border-radius:13px;padding:17px;box-shadow:0 10px 25px #2238470c}.card h2{font-size:15px;margin:0 0 14px}.statlabel,.muted{color:var(--muted)}.stat{font-size:27px;font-weight:650;color:var(--accent);margin:8px 0}.statfoot{color:var(--muted);font-size:11px}.kpi{position:relative;overflow:hidden}.kpi:after{content:"";position:absolute;right:-20px;bottom:-34px;width:95px;height:95px;border-radius:50%;background:#e8f1f2}.quickgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.quick{text-align:left;padding:13px}.quick b{display:block;font-size:12px;margin-bottom:4px}.quick small{color:var(--muted)}.service{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line)}.sdot{width:8px;height:8px;border-radius:50%;background:#55bd8a;display:inline-block;margin-right:8px}.sdot.off{background:#b8c0c6}.badge{font-size:11px;padding:4px 8px;border-radius:99px;background:#eaf5ef;color:var(--ok)}.badge.off{background:#f0f2f4;color:#78838b}button,input,select,textarea{font:inherit}button{border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);padding:9px 12px;cursor:pointer}button:hover{border-color:#6c9599}button.primary{background:var(--accent);border-color:var(--accent);color:#fff}button.danger{background:#fff5f5;border-color:#ebcccc;color:var(--bad)}input,select,textarea{width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:#fbfcfd;color:var(--ink);outline:0}.row input,.row select{flex:1;min-width:190px}.form{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.field label{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.wide{grid-column:1/-1}.wrap{overflow:auto;border:1px solid var(--line);border-radius:9px;margin-top:14px}table{width:100%;border-collapse:collapse;min-width:620px}th,td{padding:10px 11px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted);background:#f7f9fa}tbody tr:hover{background:#f3f8f9;cursor:pointer}.notice{padding:10px 12px;border-radius:8px;background:#eff6f7;border:1px solid #d4e5e7;color:#41646a;font-size:12px}.notice.warn{background:#fff8ec;border-color:#efdfbd;color:#855c26}.editor{height:520px;margin-top:14px;resize:vertical;font:12px Consolas,monospace}.code{padding:14px;border-radius:9px;background:#1e2c34;color:#dcebed;white-space:pre-wrap;font:12px Consolas,monospace;line-height:1.6}.empty{text-align:center;padding:24px;color:var(--muted)}.toast{display:none;position:fixed;right:22px;bottom:22px;background:#1e2c34;color:#fff;padding:13px 16px;border-radius:9px;max-width:370px}.toast.show{display:block}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.form{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.app{display:block}.side{padding:11px}.brand{padding-bottom:11px}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap}.foot{display:none}.top{padding:0 15px}.content{padding:17px 15px}.grid,.form{grid-template-columns:1fr}.quickgrid{grid-template-columns:repeat(2,1fr)}.head{display:block}}
.item-toolbar{display:grid;grid-template-columns:1.1fr 1fr auto;gap:10px;align-items:end}.live{display:inline-flex;gap:7px;align-items:center;color:var(--ok);font-size:12px}.live:before{content:"";width:8px;height:8px;border-radius:50%;background:#55bd8a;box-shadow:0 0 0 4px #e5f3eb}.storage-layout{display:grid;grid-template-columns:1fr 1fr;gap:15px}.storage-grid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:6px;padding:10px;background:#f6f8f9;border:1px solid var(--line);border-radius:9px}.storage-slot{min-height:74px;padding:6px 4px;border:1px solid #d2dfe2;border-radius:8px;background:#fff;text-align:center;cursor:pointer;overflow:hidden}.storage-slot:hover,.storage-slot.selected{border-color:var(--accent);box-shadow:0 0 0 2px #d5e8e9}.storage-slot.empty{background:#fbfcfd;color:#a6b1b7}.storage-slot .slotnum{display:block;color:#91a0a7;font-size:10px}.storage-slot .sloticon{font-size:21px;line-height:25px}.storage-slot .slotname{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.storage-slot .slotlvl{display:block;color:var(--accent);font-size:10px}.itemtiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;max-height:430px;overflow:auto;padding:2px}.itemtile{min-width:0;padding:8px 5px;border:1px solid var(--line);border-radius:9px;background:linear-gradient(150deg,#fff,#f0f5f6);text-align:center;cursor:pointer}.itemtile:hover{border-color:var(--accent);transform:translateY(-1px)}.itemicon{width:38px;height:38px;margin:0 auto 5px;border-radius:10px;background:linear-gradient(135deg,#dcecef,#70989b);display:grid;place-items:center;font-size:22px}.itemtile b{display:block;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.itemtile small{display:block;color:var(--muted);font-size:9px}.item-selected{padding:11px;border:1px solid #cfe1e3;background:#f2f8f8;border-radius:9px}.storage-meta{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:10px}.storage-meta h2{margin:0}.bag-editor{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.bag-editor .wide{grid-column:1/-1}@media(max-width:1100px){.storage-layout{grid-template-columns:1fr}.item-toolbar{grid-template-columns:1fr}.storage-grid{grid-template-columns:repeat(6,minmax(0,1fr))}}@media(max-width:700px){.storage-grid{grid-template-columns:repeat(4,minmax(58px,1fr))}.bag-editor{grid-template-columns:repeat(2,1fr)}.itemtiles{grid-template-columns:repeat(3,1fr)}}\n</style></head><body><div class="app"><aside class="side"><div class="brand"><div class="mark">G</div><div><b>GENESYS CONTROL</b><small>MU ONLINE • ADMIN CENTER</small></div></div><div class="label">Operação</div><div class="nav"><button data-v="dash" class="sel"><i>⌂</i>Visão geral</button><button data-v="acc"><i>◉</i>Contas e moedas</button><button data-v="char"><i>♙</i>Personagens</button><button data-v="on"><i>●</i>Jogadores online</button></div><div class="label">Configuração</div><div class="nav"><button data-v="srv"><i>⚙</i>Servidor</button><button data-v="item"><i>◇</i>Itens</button><button data-v="bag"><i>▦</i>Inventário e baú</button><button data-v="event"><i>◷</i>Eventos e spots</button><button data-v="file"><i>▤</i>Editor de arquivos</button></div><div class="foot"><span class="dot"></span><span id="status">Conectando...</span><br><span id="profile">Perfil local</span></div></aside><main class="main"><header class="top"><div class="crumb">Genesys Control Center<b id="title">Visão geral</b></div><div class="tools"><select id="profiles" style="width:220px"></select><button onclick="loadAll()">↻ Atualizar</button><button class="primary" onclick="makeBackup()">Criar backup</button></div></header><div class="content">
<section id="dash" class="view on"><div class="head"><div><h1>Visão geral</h1><p>Operação rápida e segura do seu MuServer.</p></div></div><div class="grid"><div class="card kpi"><div class="statlabel">Contas cadastradas</div><div id="ka" class="stat">—</div><div class="statfoot">Banco MuOnline</div></div><div class="card kpi"><div class="statlabel">Personagens</div><div id="kc" class="stat">—</div><div class="statfoot">Total do servidor</div></div><div class="card kpi"><div class="statlabel">Online agora</div><div id="ko" class="stat">—</div><div class="statfoot">Sessões conectadas</div></div><div class="card kpi"><div class="statlabel">Serviços ativos</div><div id="ks" class="stat">—</div><div id="ksf" class="statfoot">Verificando</div></div></div><div class="grid2" style="margin-top:15px"><div class="card"><h2>Ações administrativas rápidas</h2><div class="quickgrid"><button class="quick" onclick="go('char')"><b>Editar personagem</b><small>Stats, nível, reset e zen</small></button><button class="quick" onclick="go('acc')"><b>Moedas e conta</b><small>WCoin e bloqueio</small></button><button class="quick" onclick="go('item')"><b>Montar item</b><small>Adicionais e /make</small></button><button class="quick" onclick="go('srv')"><b>Experiência e drop</b><small>Taxas do GameServer</small></button><button class="quick" onclick="go('event')"><b>Eventos e spots</b><small>Horários e monstros</small></button><button class="quick" onclick="makeBackup()"><b>Backup</b><small>Antes de editar</small></button></div></div><div class="card"><h2>Status dos serviços</h2><div id="services"><div class="empty">Carregando...</div></div></div></div><div class="card" style="margin-top:15px"><h2>Jogadores online</h2><div id="dashOnline"><div class="empty">Carregando...</div></div></div></section>
<section id="acc" class="view"><div class="head"><div><h1>Contas e moedas</h1><p>Pesquisa, bloqueio, nível e moedas do CashShop.</p></div></div><div class="card"><div class="row"><input id="aq" placeholder="Login ou nome da conta"><button class="primary" onclick="searchAcc()">Pesquisar</button></div><div class="wrap"><table><thead><tr><th>Login</th><th>Nome</th><th>Nível</th><th>Chars</th><th>Status</th><th></th></tr></thead><tbody id="accRows"><tr><td colspan="6" class="empty">Pesquise uma conta.</td></tr></tbody></table></div></div><div id="accEdit" class="card" style="display:none;margin-top:15px"><h2>Editar conta <span id="accTitle" class="muted"></span></h2><div class="form"><div class="field"><label>Login</label><input id="aId" readonly></div><div class="field"><label>Nome</label><input id="aName" readonly></div><div class="field"><label>Nível</label><input id="aLevel" type="number"></div><div class="field"><label>Bloqueio</label><input id="aLock" type="number"></div><div class="field"><label>WCoinC</label><input id="aWc" type="number"></div><div class="field"><label>WCoinP</label><input id="aWp" type="number"></div><div class="field"><label>GoblinPoint</label><input id="aGp" type="number"></div><div class="field"><label>Bloqueio chat</label><input id="aChat" type="number"></div></div><div class="actions"><button class="primary" onclick="saveAcc()">Salvar conta</button><button onclick="resetPwd()">Redefinir senha</button><button class="danger" onclick="lockAcc()">Bloquear</button></div></div></section>
<section id="char" class="view"><div class="head"><div><h1>Personagens</h1><p>Controle de nível, atributos, resets, zen e posição.</p></div><button class="primary" onclick="newChar()">+ Novo personagem</button></div><div class="card"><div class="row"><input id="cq" placeholder="Nome ou conta"><button class="primary" onclick="searchChar()">Pesquisar</button></div><div class="wrap"><table><thead><tr><th>Nome</th><th>Conta</th><th>Nível</th><th>Experiência</th><th>Zen</th><th>Reset</th><th>Mapa</th></tr></thead><tbody id="charRows"><tr><td colspan="7" class="empty">Pesquise um personagem.</td></tr></tbody></table></div></div><div id="charNew" class="card" style="display:none;margin-top:15px"><h2>Novo personagem</h2><div class="notice">A conta precisa existir no banco. Os demais atributos começam zerados e podem ser ajustados depois.</div><div class="form" style="margin-top:14px"><div class="field"><label>Nome</label><input id="nName" maxlength="10"></div><div class="field"><label>Conta</label><input id="nAcc" maxlength="10"></div><div class="field"><label>Classe</label><input id="nClass" type="number" min="0" max="6" value="0"></div><div class="field"><label>Nível</label><input id="nLev" type="number" min="1" value="1"></div><div class="field"><label>Zen</label><input id="nMon" type="number" min="0" value="0"></div><div class="field"><label>Mapa</label><input id="nMap" type="number" value="0"></div><div class="field"><label>Posição X</label><input id="nX" type="number" value="125"></div><div class="field"><label>Posição Y</label><input id="nY" type="number" value="125"></div></div><div class="actions"><button class="primary" onclick="createChar()">Criar personagem</button><button onclick="$('charNew').style.display='none'">Cancelar</button></div></div><div id="charEdit" class="card" style="display:none;margin-top:15px"><h2>Editar personagem <span id="charTitle" class="muted"></span></h2><div class="notice warn">Se estiver online, o GameServer pode sobrescrever os dados. Desconecte-o antes de alterações críticas.</div><div class="form" style="margin-top:14px"><div class="field"><label>Nome</label><input id="cName" readonly></div><div class="field"><label>Conta</label><input id="cAcc"></div><div class="field"><label>Nível</label><input id="cLev" type="number"></div><div class="field"><label>Experiência</label><input id="cExp" type="number"></div><div class="field"><label>Força</label><input id="cStr" type="number"></div><div class="field"><label>Agilidade</label><input id="cDex" type="number"></div><div class="field"><label>Vitalidade</label><input id="cVit" type="number"></div><div class="field"><label>Energia</label><input id="cEne" type="number"></div><div class="field"><label>Liderança</label><input id="cLead" type="number"></div><div class="field"><label>Zen</label><input id="cMon" type="number"></div><div class="field"><label>Reset</label><input id="cRes" type="number"></div><div class="field"><label>Master Reset</label><input id="cMRes" type="number"></div><div class="field"><label>Mapa</label><input id="cMap" type="number"></div><div class="field"><label>Posição X</label><input id="cX" type="number"></div><div class="field"><label>Posição Y</label><input id="cY" type="number"></div><div class="field"><label>PK Level</label><input id="cPk" type="number"></div><div class="field"><label>Control Code</label><input id="cCtl" type="number"></div><div class="field"><label>Pontos</label><input id="cPts" type="number"></div><div class="field"><label>FruitPoint</label><input id="cFruit" type="number"></div></div><div class="actions"><button class="primary" onclick="saveChar()">Salvar personagem</button><button onclick="resetStats()">Zerar atributos</button></div></div></section>
<section id="on" class="view"><div class="head"><div><h1>Jogadores online</h1><p>Sessões ativas no banco de dados.</p></div><button onclick="loadOnline()">↻ Atualizar lista</button></div><div class="card" id="onlineTable"><div class="empty">Carregando...</div></div></section>
<section id="srv" class="view"><div class="head"><div><h1>Configuração do servidor</h1><p>Taxas ligadas ao Common.dat do GameServer.</p></div></div><div class="card"><div class="notice">Cada salvamento cria uma cópia de segurança. Algumas mudanças exigem <b>/reload</b> ou reinício do GameServer.</div><div class="form" style="margin-top:15px"><div class="field"><label>Experiência normal</label><input id="xExp" type="number"></div><div class="field"><label>Experiência Master</label><input id="xMaster" type="number"></div><div class="field"><label>Vida dos monstros (%)</label><input id="xLife" type="number"></div><div class="field"><label>Drop de itens (%)</label><input id="xItem" type="number"></div><div class="field"><label>Drop de Zen (%)</label><input id="xMoney" type="number"></div><div class="field"><label>Limite de jogadores</label><input id="xMax" type="number"></div><div class="field"><label>ServerLock</label><input id="xLock" type="number"></div><div class="field"><label>Manutenção</label><input id="xMaint" type="number"></div></div><div class="actions"><button class="primary" onclick="saveCfg()">Salvar configurações</button><button onclick="loadDash()">Recarregar</button></div><div class="row" style="margin-top:18px"><input id="xKey" placeholder="Chave avançada do Common.dat"><input id="xVal" placeholder="Valor"><button class="primary" onclick="saveAdv()">Salvar chave</button></div></div></section>
<section id="item" class="view"><div class="head"><div><h1>Editor de itens</h1><p>Catálogo do Item.txt e gerador de /make.</p></div></div><div class="grid2"><div class="card"><div class="row"><input id="iq" placeholder="Buscar item ou código" oninput="filterItems()"></div><div class="wrap"><table><thead><tr><th>Código</th><th>Grupo</th><th>Item</th><th>Nível</th></tr></thead><tbody id="itemRows"><tr><td colspan="4" class="empty">Carregando...</td></tr></tbody></table></div></div><div class="card"><h2>Montar item administrativo</h2><div class="notice">O servidor possui <b>/make</b>. Gere a linha pronta para executar com o personagem ADM.</div><div class="form" style="margin-top:15px"><div class="field wide"><label>Item selecionado</label><input id="iSel" readonly></div><div class="field"><label>Grupo</label><input id="iG" type="number"></div><div class="field"><label>Índice</label><input id="iI" type="number"></div><div class="field"><label>Nível</label><input id="iL" type="number" value="0"></div><div class="field"><label>Skill</label><input id="iSk" type="number" value="0"></div><div class="field"><label>Luck</label><input id="iLu" type="number" value="0"></div><div class="field"><label>Option</label><input id="iOp" type="number" value="0"></div><div class="field"><label>Excellent</label><input id="iEx" type="number" value="0"></div><div class="field"><label>Set</label><input id="iSet" type="number" value="0"></div><div class="field"><label>Socket</label><input id="iSo" type="number" value="0"></div><div class="field wide"><label>Comando /make</label><input id="iCmd" readonly></div></div><div class="actions"><button class="primary" onclick="makeCmd()">Gerar comando</button><button onclick="copyCmd()">Copiar</button></div><div id="itemPreview" class="code" style="margin-top:13px">Selecione um item e gere o comando.</div></div></div></section>
<section id="bag" class="view"><div class="head"><div><h1>Inventário e baú</h1><p>Selecione conta, personagem e edite os slots com persistência no SQL.</p></div><span class="live">Banco conectado • atualização a cada 5s</span></div><div class="card"><div class="item-toolbar"><div class="field"><label>Conta</label><select id="bagAcc" onchange="loadBagChars()"><option>Carregando...</option></select></div><div class="field"><label>Personagem</label><select id="bagChar" onchange="loadStorage()"><option>Selecione uma conta</option></select></div><button class="primary" onclick="loadStorage()">↻ Atualizar armazenamento</button></div></div><div class="grid2" style="margin-top:15px"><div class="card"><h2>Exemplos de itens</h2><div class="notice">Escolha um item do catálogo para preencher o editor. A prévia usa o grupo e índice reais do Item.txt.</div><input id="bagItemSearch" style="margin-top:12px" placeholder="Pesquisar nome ou código" oninput="renderBagExamples()"><div id="bagItemExamples" class="itemtiles" style="margin-top:12px"><div class="empty">Carregando catálogo...</div></div></div><div class="card"><h2>Editor do item selecionado</h2><div id="bagItemLabel" class="item-selected">Selecione um slot ou item de exemplo.</div><div class="bag-editor" style="margin-top:12px"><div class="field"><label>Área</label><select id="bagArea" onchange="selectBagArea()"><option value="inventory">Inventário</option><option value="warehouse">Baú principal</option></select></div><div class="field"><label>Slot</label><input id="bagSlot" type="number" min="0" value="0" onchange="selectStorageSlot($('bagArea').value,Number(this.value))"></div><div class="field"><label>Grupo</label><input id="bagGroup" type="number" min="0" max="15"></div><div class="field"><label>Índice</label><input id="bagIndex" type="number" min="0" max="255"></div><div class="field"><label>Nível</label><input id="bagLevel" type="number" min="0" max="15" value="0"></div><div class="field"><label>Skill</label><input id="bagSkill" type="number" min="0" max="1" value="0"></div><div class="field"><label>Luck</label><input id="bagLuck" type="number" min="0" max="1" value="0"></div><div class="field"><label>Option</label><input id="bagOption" type="number" min="0" max="7" value="0"></div><div class="field"><label>Excellent (0–63)</label><input id="bagExcellent" type="number" min="0" max="63" value="0"></div><div class="field"><label>Ancient</label><input id="bagAncient" type="number" min="0" max="15" value="0"></div><div class="field"><label>Refine</label><input id="bagRefine" type="number" min="0" max="15" value="0"></div><div class="field"><label>Durabilidade</label><input id="bagDurability" type="number" min="0" max="255" value="255"></div><div class="field"><label>Harmony tipo</label><input id="bagHarmonyType" type="number" min="0" max="15" value="0"></div><div class="field"><label>Harmony nível</label><input id="bagHarmonyLevel" type="number" min="0" max="15" value="0"></div><div class="field"><label>Socket 1</label><input id="bagSock1" type="number" min="0" max="255" value="255"></div><div class="field"><label>Socket 2</label><input id="bagSock2" type="number" min="0" max="255" value="255"></div><div class="field"><label>Socket 3</label><input id="bagSock3" type="number" min="0" max="255" value="255"></div><div class="field"><label>Socket 4</label><input id="bagSock4" type="number" min="0" max="255" value="255"></div><div class="field"><label>Socket 5</label><input id="bagSock5" type="number" min="0" max="255" value="255"></div></div><div class="actions" style="margin-top:14px"><button class="primary" onclick="saveBagItem()">Salvar no slot selecionado</button><button class="danger" onclick="clearBagSlot()">Limpar slot</button></div><div id="bagHex" class="code" style="margin-top:13px">Selecione um slot para visualizar o código.</div></div></div><div class="storage-layout" style="margin-top:15px"><div class="card"><div class="storage-meta"><h2>Inventário do personagem</h2><span class="muted" id="invCount">—</span></div><div class="notice warn">Os 12 primeiros slots são equipamento; os demais são inventário. Para evitar conflitos, salve com o personagem offline.</div><div id="inventoryGrid" class="storage-grid" style="margin-top:12px"><div class="empty">Selecione um personagem.</div></div></div><div class="card"><div class="storage-meta"><h2>Baú principal da conta</h2><span class="muted" id="boxCount">—</span></div><div class="notice">Este painel grava a tabela <b>warehouse</b> do perfil selecionado.</div><div id="warehouseGrid" class="storage-grid" style="margin-top:12px"><div class="empty">Selecione um personagem.</div></div></div></div></section><section id="event" class="view"><div class="head"><div><h1>Eventos e spots</h1><p>Horários e MonsterSetBase com backup automático.</p></div></div><div class="card"><div class="row"><select id="eventFiles"></select><button onclick="openFile('event')">Abrir</button><button class="primary" onclick="saveFile('event')">Salvar</button></div><textarea id="eventText" class="editor" spellcheck="false"></textarea></div></section>
<section id="file" class="view"><div class="head"><div><h1>Editor de arquivos</h1><p>Acesso controlado aos arquivos de configuração.</p></div></div><div class="card"><div class="row"><select id="allFiles"></select><button onclick="openFile('all')">Abrir</button><button class="primary" onclick="saveFile('all')">Salvar</button></div><textarea id="fileText" class="editor" spellcheck="false"></textarea></div></section>
</div></main></div><div id="toast" class="toast"></div><script>
var $=function(id){return document.getElementById(id)},S={items:[],files:[],storage:null,bagArea:'inventory',bagSlot:0};
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]})}
function toast(t,b){var x=$('toast');x.textContent=t;x.style.background=b?'#8f4747':'#1e2c34';x.classList.add('show');setTimeout(function(){x.classList.remove('show')},3000)}
function api(p,o){return fetch(p,Object.assign({headers:{'Content-Type':'application/json'}},o||{})).then(function(r){return r.json().then(function(j){if(!r.ok)throw Error(j.error||'Falha');return j})})}
function go(v){document.querySelectorAll('.view').forEach(function(x){x.classList.remove('on')});document.querySelectorAll('.nav button').forEach(function(x){x.classList.toggle('sel',x.dataset.v===v)});$(v).classList.add('on');$('title').textContent=$(v).querySelector('h1').textContent;if(v==='on')loadOnline();if(v==='item'&&!S.items.length)loadItems();if(v==='bag'){if(!S.items.length)loadItems().then(function(){renderBagExamples()});else renderBagExamples();loadBagAccounts()}if(v==='event')loadFiles('event');if(v==='file')loadFiles('all')}
document.querySelectorAll('.nav button').forEach(function(x){x.onclick=function(){go(x.dataset.v)}})
function loadAll(){Promise.all([loadProfiles(),loadDash(),loadFiles('all'),loadItems()]).catch(function(e){toast(e.message,true)})}
var liveTimer=setInterval(function(){loadDash().catch(function(){});var v=document.querySelector('.view.on');if(v&&v.id==='on')loadOnline().catch(function(){});if(v&&v.id==='bag'&&$('bagAcc').value&&$('bagChar').value)loadStorage().catch(function(){})},5000);
function loadProfiles(){return api('/api/profiles').then(function(j){$('profiles').innerHTML=j.profiles.map(function(p){return '<option value="'+esc(p.Id)+'" '+(p.Id===j.active?'selected':'')+'>'+esc(p.Name)+'</option>'}).join('');$('profiles').onchange=function(e){api('/api/profile',{method:'POST',body:JSON.stringify({id:e.target.value})}).then(function(){location.reload()})}})}
function loadDash(){return api('/api/dashboard').then(function(j){$('ka').textContent=Number(j.counts.accounts).toLocaleString('pt-BR');$('kc').textContent=Number(j.counts.characters).toLocaleString('pt-BR');$('ko').textContent=Number(j.counts.online).toLocaleString('pt-BR');var n=j.services.filter(function(x){return x.running}).length;$('ks').textContent=n+'/'+j.services.length;$('ksf').textContent=j.database?'SQL conectado':'SQL indisponível';$('status').textContent=j.database?'Servidor e banco conectados':'Banco indisponível';$('profile').textContent=j.profile.Name;$('services').innerHTML=j.services.map(function(s){return '<div class="service"><span><span class="sdot '+(s.running?'':'off')+'"></span>'+esc(s.name)+'</span><span class="badge '+(s.running?'':'off')+'">'+(s.running?'Online':'Parado')+'</span></div>'}).join('');var ids=['xExp','xMaster','xLife','xItem','xMoney','xMax','xLock','xMaint'],v=[j.config.exp,j.config.master,j.config.life,j.config.item,j.config.money,j.config.max,j.config.lock,j.config.maint];ids.forEach(function(x,i){$(x).value=v[i]});return api('/api/online')}).then(function(j){$('dashOnline').innerHTML=table(j.rows.slice(0,8))})}
function table(a){if(!a.length)return'<div class="empty">Nenhum jogador online.</div>';var s='<div class="wrap"><table><thead><tr><th>Personagem</th><th>Conta</th><th>Nível</th><th>Mapa</th><th>Servidor</th></tr></thead><tbody>';s+=a.map(function(x){return'<tr><td>'+esc(x.Name)+'</td><td>'+esc(x.AccountID)+'</td><td>'+esc(x.cLevel)+'</td><td>'+esc(x.MapNumber)+'</td><td>'+esc(x.ServerName)+'</td></tr>'}).join('');return s+'</tbody></table></div>'}
function loadOnline(){api('/api/online').then(function(j){$('onlineTable').innerHTML=table(j.rows)})}
function searchAcc(){var q=$('aq').value.trim();if(!q)return toast('Informe o login ou nome',true);api('/api/accounts?q='+encodeURIComponent(q)).then(function(j){$('accRows').innerHTML=j.rows.length?j.rows.map(function(x){return'<tr><td>'+esc(x.AccountID)+'</td><td>'+esc(x.AccountName)+'</td><td>'+esc(x.AccountLevel)+'</td><td>'+esc(x.CharCount)+'</td><td><span class="badge '+(x.ConnectStat>0?'':'off')+'">'+(x.ConnectStat>0?'Online':'Offline')+'</span></td><td><button onclick="openAcc(\''+esc(x.AccountID)+'\')">Editar</button></td></tr>'}).join(''):'<tr><td colspan="6" class="empty">Nenhuma conta.</td></tr>'})}
function openAcc(id){api('/api/account?id='+encodeURIComponent(id)).then(function(j){var a=j.account;if(!a)return toast('Conta não encontrada',true);$('accEdit').style.display='block';$('accTitle').textContent='• '+a.AccountID;$('aId').value=a.AccountID;$('aName').value=a.AccountName;$('aLevel').value=a.AccountLevel;$('aLock').value=a.AccountLock;$('aChat').value=a.BlocChat;$('aWc').value=a.Coins&&a.Coins.WCoinC||0;$('aWp').value=a.Coins&&a.Coins.WCoinP||0;$('aGp').value=a.Coins&&a.Coins.GoblinPoint||0;$('accEdit').scrollIntoView({behavior:'smooth'})})}
function saveAcc(){api('/api/action',{method:'POST',body:JSON.stringify({action:'account.save',AccountID:$('aId').value,AccountLevel:$('aLevel').value,tLock:$('aLock').value,tBloc_chat:$('aChat').value,tWCoinC:$('aWc').value,tWCoinP:$('aWp').value,tGoblinPoint:$('aGp').value})}).then(function(){toast('Conta atualizada')}).catch(function(e){toast(e.message,true)})}
function lockAcc(){if(confirm('Bloquear esta conta?')){$('aLock').value=1;saveAcc()}}function resetPwd(){var p=prompt('Nova senha (mínimo 4 caracteres):');if(!p)return;api('/api/action',{method:'POST',body:JSON.stringify({action:'account.password',AccountID:$('aId').value,Password:p})}).then(function(){toast('Senha redefinida')}).catch(function(e){toast(e.message,true)})}
function searchChar(){var q=$('cq').value.trim();if(!q)return toast('Informe o nome ou conta',true);api('/api/characters?q='+encodeURIComponent(q)).then(function(j){$('charRows').innerHTML=j.rows.length?j.rows.map(function(x){return'<tr onclick="openChar(\''+esc(x.Name)+'\')"><td>'+esc(x.Name)+'</td><td>'+esc(x.AccountID)+'</td><td>'+esc(x.cLevel)+'</td><td>'+Number(x.Experience||0).toLocaleString('pt-BR')+'</td><td>'+Number(x.Money||0).toLocaleString('pt-BR')+'</td><td>'+esc(x.ResetCount)+'</td><td>'+esc(x.MapNumber)+'</td></tr>'}).join(''):'<tr><td colspan="7" class="empty">Nenhum personagem.</td></tr>'})}
function openChar(name){api('/api/character?name='+encodeURIComponent(name)).then(function(j){var c=j.character;if(!c)return toast('Personagem não encontrado',true);$('charEdit').style.display='block';$('charTitle').textContent='• '+c.Name;var m={cName:'Name',cAcc:'AccountID',cLev:'cLevel',cExp:'Experience',cStr:'Strength',cDex:'Dexterity',cVit:'Vitality',cEne:'Energy',cLead:'Leadership',cMon:'Money',cRes:'ResetCount',cMRes:'MasterResetCount',cMap:'MapNumber',cX:'MapPosX',cY:'MapPosY',cPk:'PKLevel',cCtl:'CtlCode',cPts:'LevelUpPoint',cFruit:'FruitPoint'};Object.keys(m).forEach(function(i){$(i).value=c[m[i]]==null?'':c[m[i]]});$('charEdit').scrollIntoView({behavior:'smooth'})})}
function newChar(){$('charNew').style.display='block';$('charEdit').style.display='none';$('nAcc').value=$('cq').value.trim();$('nName').value='';$('charNew').scrollIntoView({behavior:'smooth'})}
function createChar(){var d={action:'character.create',Name:$('nName').value.trim(),AccountID:$('nAcc').value.trim(),Class:$('nClass').value,cLevel:$('nLev').value,Experience:0,Strength:0,Dexterity:0,Vitality:0,Energy:0,Leadership:0,Money:$('nMon').value,MapNumber:$('nMap').value,MapPosX:$('nX').value,MapPosY:$('nY').value,PKLevel:3,CtlCode:0,LevelUpPoint:0,FruitPoint:0,ResetCount:0,MasterResetCount:0};if(!d.Name||!d.AccountID)return toast('Informe nome e conta',true);api('/api/action',{method:'POST',body:JSON.stringify(d)}).then(function(){toast('Personagem criado');$('charNew').style.display='none';$('cq').value=d.Name;searchChar()}).catch(function(e){toast(e.message,true)})}
function charData(){return{Name:$('cName').value,AccountID:$('cAcc').value,cLevel:$('cLev').value,Experience:$('cExp').value,Strength:$('cStr').value,Dexterity:$('cDex').value,Vitality:$('cVit').value,Energy:$('cEne').value,Leadership:$('cLead').value,Money:$('cMon').value,ResetCount:$('cRes').value,MasterResetCount:$('cMRes').value,MapNumber:$('cMap').value,MapPosX:$('cX').value,MapPosY:$('cY').value,PKLevel:$('cPk').value,CtlCode:$('cCtl').value,LevelUpPoint:$('cPts').value,FruitPoint:$('cFruit').value}}
function saveChar(){api('/api/action',{method:'POST',body:JSON.stringify(Object.assign({action:'character.save'},charData()))}).then(function(){toast('Personagem atualizado')}).catch(function(e){toast(e.message,true)})}function resetStats(){if(!confirm('Zerar atributos deste personagem?'))return;api('/api/action',{method:'POST',body:JSON.stringify({action:'character.reset',Name:$('cName').value})}).then(function(){toast('Atributos zerados');openChar($('cName').value)}).catch(function(e){toast(e.message,true)})}
function saveCfg(){var a=[['AddExperienceRate_AL0','xExp'],['AddMasterExperienceRate_AL0','xMaster'],['MonsterLifeRate','xLife'],['ItemDropRate_AL0','xItem'],['MoneyAmountDropRate_AL0','xMoney'],['ServerMaxUserNumber','xMax'],['ServerLock','xLock'],['ServerMaintenance','xMaint']].map(function(x){return{key:x[0],value:$(x[1]).value}});api('/api/action',{method:'POST',body:JSON.stringify({action:'config.save',values:a})}).then(function(){toast('Configurações salvas')}).catch(function(e){toast(e.message,true)})}function saveAdv(){if(!$('xKey').value||!$('xVal').value)return toast('Informe chave e valor',true);api('/api/action',{method:'POST',body:JSON.stringify({action:'config.save',values:[{key:$('xKey').value,value:$('xVal').value}]})}).then(function(){toast('Chave salva')}).catch(function(e){toast(e.message,true)})}
function loadItems(){return api('/api/items').then(function(j){S.items=j.items;renderItems(S.items)})}function filterItems(){var q=$('iq').value.toLowerCase();renderItems(S.items.filter(function(x){return(x.name+' '+x.code).toLowerCase().indexOf(q)>=0}))}function renderItems(a){$('itemRows').innerHTML=a.slice(0,500).map(function(x){return'<tr onclick="selectItem('+x.group+','+x.index+')"><td>'+x.code+'</td><td>'+x.group+'</td><td>'+esc(x.name)+'</td><td>'+x.level+'</td></tr>'}).join('')||'<tr><td colspan="4" class="empty">Nenhum item.</td></tr>'}function selectItem(g,i){var x=S.items.find(function(y){return y.group===g&&y.index===i});$('iSel').value=x.name+' • código '+x.code;$('iG').value=x.group;$('iI').value=x.index;makeCmd()}function makeCmd(){var a=['iG','iI','iL','iSk','iLu','iOp','iEx','iSet','iSo'].map(function(i){return $(i).value||0}),c='/make '+a.join(' ');$('iCmd').value=c;$('itemPreview').textContent=c+'\\n\\nExecute com o personagem ADM configurado no servidor.';return c}function copyCmd(){navigator.clipboard.writeText(makeCmd()).then(function(){toast('Comando copiado')})}
function bagIcon(g){return ['🗡️','🛡️','🏹','🪄','🪓','👕','💍','🪽','🎩','💎','🧿','🧪','📜','🧰','⚔️','🔮'][Number(g)||0]||'✦'}function loadBagAccounts(){return api('/api/accounts?q=%25').then(function(j){var a=j.rows||[];$('bagAcc').innerHTML=a.map(function(x){return'<option value="'+esc(x.AccountID)+'">'+esc(x.AccountID)+' • '+esc(x.AccountName||'')+'</option>'}).join('')||'<option value="">Nenhuma conta</option>';return loadBagChars()}).catch(function(e){toast(e.message,true)})}function loadBagChars(){var a=$('bagAcc').value;if(!a){$('bagChar').innerHTML='<option value="">Nenhum personagem</option>';return Promise.resolve()};return api('/api/characters?q='+encodeURIComponent(a)).then(function(j){var r=(j.rows||[]).filter(function(x){return x.AccountID===a});$('bagChar').innerHTML=r.map(function(x){return'<option value="'+esc(x.Name)+'">'+esc(x.Name)+' • nível '+esc(x.cLevel)+'</option>'}).join('')||'<option value="">Nenhum personagem</option>';return r.length?loadStorage():null}).catch(function(e){toast(e.message,true)})}function loadStorage(){var a=$('bagAcc').value,c=$('bagChar').value;if(!a||!c)return Promise.resolve();return api('/api/storage?account='+encodeURIComponent(a)+'&character='+encodeURIComponent(c)).then(function(j){S.storage=j;S.bagArea=$('bagArea').value||'inventory';renderStorage();renderBagExamples()})}function renderStorage(){if(!S.storage)return;function draw(area,id){var d=S.storage[area==='inventory'?'inventory':'warehouse'],filled=d.slots.filter(function(x){return!x.empty}).length;$(area==='inventory'?'invCount':'boxCount').textContent=filled+' / '+d.slots.length+' ocupados';$(id).innerHTML=d.slots.map(function(x){var cls='storage-slot '+(x.empty?'empty':'')+(S.bagArea===area&&S.bagSlot===x.slot?' selected':'');return'<button class="'+cls+'" data-area="'+area+'" data-slot="'+x.slot+'" onclick="selectStorageSlot(this.dataset.area,Number(this.dataset.slot))"><span class="slotnum">#'+x.slot+'</span><span class="sloticon">'+(x.empty?'＋':bagIcon(x.group))+'</span><span class="slotname">'+esc(x.empty?'Vazio':x.name)+'</span><span class="slotlvl">'+(x.empty?'':'+'+x.level)+'</span></button>'}).join('')}draw('inventory','inventoryGrid');draw('warehouse','warehouseGrid')}function renderBagExamples(){if(!$('bagItemExamples'))return;var q=($('bagItemSearch').value||'').toLowerCase();var a=S.items.filter(function(x){return(x.name+' '+x.code+' '+x.group).toLowerCase().indexOf(q)>=0}).slice(0,100);$('bagItemExamples').innerHTML=a.map(function(x){return'<button class="itemtile" onclick="chooseBagItem('+x.group+','+x.index+')"><span class="itemicon">'+bagIcon(x.group)+'</span><b title="'+esc(x.name)+'">'+esc(x.name)+'</b><small>G'+x.group+' • #'+x.index+' • Nv '+x.level+'</small></button>'}).join('')||'<div class="empty">Nenhum item encontrado.</div>'}function chooseBagItem(g,i){var x=S.items.find(function(y){return y.group===g&&y.index===i});if(!x)return;$('bagGroup').value=x.group;$('bagIndex').value=x.index;$('bagItemLabel').innerHTML='<b>'+bagIcon(x.group)+' '+esc(x.name)+'</b><small>Grupo '+x.group+' • Índice '+x.index+' • código '+x.code+' • nível máximo '+x.level+'</small>';$('bagHex').textContent='Item selecionado. Salve no slot '+S.bagSlot+' para gravar.'}function setBagField(id,v){$(id).value=v==null?'':v}function selectStorageSlot(area,slot){if(!S.storage)return;var d=S.storage[area==='inventory'?'inventory':'warehouse'];slot=Number(slot);if(!Number.isInteger(slot)||slot<0||slot>=d.slots.length)return toast('Slot inválido',true);S.bagArea=area;S.bagSlot=slot;$('bagArea').value=area;$('bagSlot').value=slot;var x=d.slots[slot];if(x&&!x.empty){setBagField('bagGroup',x.group);setBagField('bagIndex',x.index);setBagField('bagLevel',x.level);setBagField('bagSkill',x.skill);setBagField('bagLuck',x.luck);setBagField('bagOption',x.option);setBagField('bagExcellent',x.excellent);setBagField('bagAncient',x.ancient);setBagField('bagRefine',x.refine);setBagField('bagDurability',x.durability);setBagField('bagHarmonyType',x.harmonyType);setBagField('bagHarmonyLevel',x.harmonyLevel);(x.sockets||[255,255,255,255,255]).forEach(function(v,n){setBagField('bagSock'+(n+1),v)});$('bagItemLabel').innerHTML='<b>'+bagIcon(x.group)+' '+esc(x.name)+'</b><small>'+x.kind+' • grupo '+x.group+' • índice '+x.index+' • serial '+esc(x.serial)+'</small>';$('bagHex').textContent=x.hex}else{['bagGroup','bagIndex'].forEach(function(id){setBagField(id,'')});['bagLevel','bagSkill','bagLuck','bagOption','bagExcellent','bagAncient','bagRefine','bagHarmonyType','bagHarmonyLevel'].forEach(function(id){setBagField(id,0)});setBagField('bagDurability',255);[1,2,3,4,5].forEach(function(n){setBagField('bagSock'+n,255)});$('bagItemLabel').innerHTML='<b>Slot vazio • '+(area==='inventory'?'Inventário':'Baú principal')+' #'+slot+'</b><small>Escolha um item de exemplo ou informe grupo e índice.</small>';$('bagHex').textContent='F'.repeat(32)};renderStorage()}function selectBagArea(){var a=$('bagArea').value;var max=a==='inventory'?250:240;var n=Math.min(Number($('bagSlot').value)||0,max-1);selectStorageSlot(a,n)}function bagPayload(action){return{action:action,area:S.bagArea,account:$('bagAcc').value,character:$('bagChar').value,slot:S.bagSlot,group:$('bagGroup').value,index:$('bagIndex').value,level:$('bagLevel').value,skill:$('bagSkill').value,luck:$('bagLuck').value,option:$('bagOption').value,excellent:$('bagExcellent').value,ancient:$('bagAncient').value,refine:$('bagRefine').value,harmonyType:$('bagHarmonyType').value,harmonyLevel:$('bagHarmonyLevel').value,durability:$('bagDurability').value,sock1:$('bagSock1').value,sock2:$('bagSock2').value,sock3:$('bagSock3').value,sock4:$('bagSock4').value,sock5:$('bagSock5').value}}function saveBagItem(){if(!$('bagAcc').value||!$('bagChar').value)return toast('Selecione conta e personagem',true);if($('bagGroup').value===''||$('bagIndex').value==='')return toast('Selecione um item do catálogo',true);api('/api/action',{method:'POST',body:JSON.stringify(bagPayload('storage.save'))}).then(function(){toast('Item salvo no armazenamento');return loadStorage()}).catch(function(e){toast(e.message,true)})}function clearBagSlot(){if(!confirm('Limpar o slot '+S.bagSlot+' de '+(S.bagArea==='inventory'?'inventário':'baú principal')+'?'))return;api('/api/action',{method:'POST',body:JSON.stringify(bagPayload('storage.clear'))}).then(function(){toast('Slot limpo');return loadStorage()}).catch(function(e){toast(e.message,true)})}function loadFiles(mode){return api('/api/files').then(function(j){S.files=j.files;var a=mode==='event'?S.files.filter(function(x){return x.path.indexOf('/Event/')>=0||x.path.indexOf('/MonsterSetBase/')>=0}):S.files,id=mode==='event'?'eventFiles':'allFiles';$(id).innerHTML=a.map(function(x){return'<option value="'+esc(x.path)+'">'+esc(x.path)+'</option>'}).join('')})}function openFile(mode){var id=mode==='event'?'eventFiles':'allFiles',ed=mode==='event'?'eventText':'fileText',p=$(id).value;if(!p)return;api('/api/file?path='+encodeURIComponent(p)).then(function(j){$(ed).value=j.content})}function saveFile(mode){var id=mode==='event'?'eventFiles':'allFiles',ed=mode==='event'?'eventText':'fileText',p=$(id).value;if(!p)return;api('/api/action',{method:'POST',body:JSON.stringify({action:'file.save',path:p,content:$(ed).value})}).then(function(){toast('Arquivo salvo com backup')}).catch(function(e){toast(e.message,true)})}function makeBackup(){api('/api/action',{method:'POST',body:JSON.stringify({action:'backup.create'})}).then(function(j){toast('Backup criado em '+j.result.path)}).catch(function(e){toast(e.message,true)})}loadAll();
</script></body></html>
'@

$Html=$Html.Replace('</style>',$EnhancementCss+'</style>')
$Html=$Html.Replace('</script>',$EnhancementJs+'</script>')
$listener=[Net.HttpListener]::new();$listener.Prefixes.Add("http://127.0.0.1:$Port/");$listener.Start();Write-Host "Genesys Control Center: http://127.0.0.1:$Port/"
try{while($listener.IsListening){$Context=$listener.GetContext();try{$p=$Context.Request.Url.AbsolutePath;$m=$Context.Request.HttpMethod
if($p-in '/','/index.html'){SendText $Context $Html 'text/html; charset=utf-8';continue}
if($p-eq'/asset'-and$m-eq'GET'){SendAsset $Context (Q $Context 'path');continue}
if($p-eq'/api/profiles'-and$m-eq'GET'){SendJson $Context @{profiles=$Profiles;active=$Active};continue}
if($p-eq'/api/profile'-and$m-eq'POST'){$b=ReadBody $Context;if(!(@($Profiles.Id)-contains$b.id)){throw'Perfil não encontrado'};$script:Active=[string]$b.id;Audit 'profile.switch' $b.id;SendJson $Context @{ok=$true};continue}
if($p-eq'/api/dashboard'-and$m-eq'GET'){SendJson $Context (Dash);continue}
if($p-eq'/api/online'-and$m-eq'GET'){SendJson $Context @{rows=@(Online)};continue}
if($p-eq'/api/accounts'-and$m-eq'GET'){SendJson $Context @{rows=@(SearchAccount(Q $Context 'q'))};continue}
if($p-eq'/api/account'-and$m-eq'GET'){SendJson $Context @{account=AccOne(Q $Context 'id')};continue}
if($p-eq'/api/characters'-and$m-eq'GET'){SendJson $Context @{rows=@(SearchChar(Q $Context 'q'))};continue}
if($p-eq'/api/character'-and$m-eq'GET'){SendJson $Context @{character=CharOne(Q $Context 'name')};continue}
if($p-eq'/api/items'-and$m-eq'GET'){SendJson $Context @{items=@(Items)};continue}
if($p-eq'/api/storage'-and$m-eq'GET'){SendJson $Context (Storage (Q $Context 'account') (Q $Context 'character'));continue}
if($p-eq'/api/files'-and$m-eq'GET'){SendJson $Context @{files=@(Files)};continue}
if($p-eq'/api/file'-and$m-eq'GET'){$f=FilePath(Q $Context 'path');SendJson $Context @{content=[IO.File]::ReadAllText($f)};continue}
if($p-eq'/api/action'-and$m-eq'POST'){$b=ReadBody $Context;SendJson $Context @{ok=$true;result=DoAction $b};continue}
SendJson $Context @{error='Rota não encontrada'} 404
}catch{try{SendJson $Context @{error=$_.Exception.Message} 400}catch{}}}}finally{$listener.Stop();$listener.Close()}

